-- 2. Merge and unpublish 34 verified exact-duplicate herb entries (never hard-delete)
DO $$
DECLARE
  v_dup_id uuid;
  v_canon_id uuid;
  v_dup_name text;
  v_canon_name text;
  v_dup_views integer;
  v_dup_names text[];
  v_dup_cits jsonb;
  v_canon_cits jsonb;
  v_pair record;
BEGIN
  FOR v_pair IN SELECT * FROM (VALUES
    ('buchu-betulina-leaf', 'buchu-roundleaf'),
    ('spirulina-platensis', 'spirulina'),
    ('berberine-source', 'mahonia-aquifolium-herb'),
    ('stachys-betonica', 'stachys-officinalis'),
    ('calophyllum-inophyllum', 'tamanu'),
    ('ipecac-root', 'ipecac'),
    ('kayu-manis-jamu', 'cinnamomum-burmanni'),
    ('calamintha-nepeta', 'clinopodium-nepeta'),
    ('quisqualis-indica', 'niyog-niyogan'),
    ('varuna-bark', 'crateva-nurvala'),
    ('amla-powder', 'amla-dried'),
    ('rhamnus-purshiana', 'frangula-purshiana'),
    ('fumitory-common', 'fumitory-herb'),
    ('galium-odoratum-herb', 'woodruff'),
    ('zimbabwean-bitter-leaf', 'maytenus-senegalensis'),
    ('pau-darco-inner', 'pau-d-arco'),
    ('haworthia-attenuata-herb', 'haworthia-attenuata'),
    ('vasaka', 'malabar-nut'),
    ('mangifera-indica', 'mango-leaf'),
    ('mentha-canadensis', 'mentha-haplocalyx'),
    ('morus-fruit', 'mulberry-fruit'),
    ('picorrhiza-kurroa', 'picrorhiza-root'),
    ('macropiper-excelsum', 'kawakawa'),
    ('piscidia-analgesic', 'piscidia-piscipula'),
    ('bai-zi-ren-seed', 'platycladus-orientalis'),
    ('korean-bellflower', 'platycodon-grandiflorus'),
    ('acacia-senegal', 'acacia'),
    ('cassia-alata', 'acapulco'),
    ('carduus-marianus', 'milk-thistle'),
    ('kantkari', 'solanum-xanthocarpum'),
    ('swertia-chirata', 'chirata'),
    ('eugenia-caryophyllata', 'clove'),
    ('fenugreek-seed', 'fenugreek'),
    ('acacia-arabica', 'acacia-nilotica')
  ) AS p(dup_slug, canon_slug) LOOP
    SELECT id, name, view_count, COALESCE(common_names, '{}'::text[]), COALESCE(citations, '[]'::jsonb)
      INTO v_dup_id, v_dup_name, v_dup_views, v_dup_names, v_dup_cits
      FROM public.herbs WHERE slug = v_pair.dup_slug;

    SELECT id, name, COALESCE(citations, '[]'::jsonb)
      INTO v_canon_id, v_canon_name, v_canon_cits
      FROM public.herbs WHERE slug = v_pair.canon_slug;

    IF v_dup_id IS NOT NULL AND v_canon_id IS NOT NULL THEN
      WITH merged_cits AS (
        SELECT elem
        FROM jsonb_array_elements(v_canon_cits) AS elem
        UNION ALL
        SELECT elem
        FROM jsonb_array_elements(v_dup_cits) AS elem
        WHERE NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(v_canon_cits) AS c
          WHERE (NULLIF(c->>'pmid','') IS NOT NULL AND c->>'pmid' = elem->>'pmid')
             OR (NULLIF(lower(c->>'url'),'') IS NOT NULL AND lower(c->>'url') = lower(elem->>'url'))
             OR (NULLIF(lower(c->>'title'),'') IS NOT NULL AND lower(c->>'title') = lower(elem->>'title'))
        )
      )
      SELECT COALESCE(jsonb_agg(elem), '[]'::jsonb) INTO v_canon_cits FROM merged_cits;

      UPDATE public.herbs h
      SET
        view_count = COALESCE(h.view_count, 0) + COALESCE(v_dup_views, 0),
        common_names = (
          SELECT COALESCE(array_agg(DISTINCT cn ORDER BY cn), '{}'::text[])
          FROM unnest(
            COALESCE(h.common_names, '{}'::text[])
            || COALESCE(v_dup_names, '{}'::text[])
            || CASE WHEN v_dup_name IS NOT NULL AND v_dup_name <> v_canon_name THEN ARRAY[v_dup_name] ELSE '{}'::text[] END
          ) AS cn
          WHERE cn IS NOT NULL AND btrim(cn) <> ''
        ),
        citations = v_canon_cits,
        updated_at = now()
      WHERE h.id = v_canon_id;

      UPDATE public.dosage_calculations SET herb_id = v_canon_id WHERE herb_id = v_dup_id;
      UPDATE public.interaction_checks SET herb_id = v_canon_id WHERE herb_id = v_dup_id;

      UPDATE public.herb_monograph_sources ms
      SET herb_slug = v_pair.canon_slug
      WHERE ms.herb_slug = v_pair.dup_slug
        AND NOT EXISTS (
          SELECT 1 FROM public.herb_monograph_sources ex
          WHERE ex.herb_slug = v_pair.canon_slug AND ex.source = ms.source
        );

      UPDATE public.herb_faqs f
      SET herb_id = v_canon_id
      WHERE f.herb_id = v_dup_id
        AND NOT EXISTS (
          SELECT 1 FROM public.herb_faqs ex
          WHERE ex.herb_id = v_canon_id AND ex.question = f.question
        );

      UPDATE public.herb_pubmed_monographs pm
      SET slug = v_pair.canon_slug
      WHERE pm.slug = v_pair.dup_slug
        AND NOT EXISTS (SELECT 1 FROM public.herb_pubmed_monographs ex WHERE ex.slug = v_pair.canon_slug);

      UPDATE public.herb_regulatory_evidence re
      SET herb_slug = v_pair.canon_slug
      WHERE re.herb_slug = v_pair.dup_slug
        AND NOT EXISTS (SELECT 1 FROM public.herb_regulatory_evidence ex WHERE ex.herb_slug = v_pair.canon_slug);

      UPDATE public.herb_monographs hm
      SET herb_id = v_canon_id, herb_slug = v_pair.canon_slug
      WHERE hm.herb_slug = v_pair.dup_slug
        AND NOT EXISTS (SELECT 1 FROM public.herb_monographs ex WHERE ex.herb_slug = v_pair.canon_slug);

      -- Never hard-delete: unpublish duplicate (permanent 308 redirect lives in data/herb-merge-redirects.json)
      UPDATE public.herbs
      SET is_published = false, updated_at = now()
      WHERE id = v_dup_id;
    END IF;
  END LOOP;
END $$;


-- 3. Normalize drug_interactions.evidence_level and backfill verified single-drug RxCUIs
UPDATE public.drug_interactions SET evidence_level = 'moderate-evidence', updated_at = now() WHERE evidence_level = 'B';
UPDATE public.drug_interactions SET evidence_level = 'well-documented', updated_at = now() WHERE evidence_level = 'monograph';
UPDATE public.drug_interactions SET evidence_level = 'well-documented', updated_at = now()
WHERE evidence_level = 'title-match' AND id IN (
  '295de202-306e-49de-9c91-740d4482d277',
  'a92746b1-aa17-4c6b-9207-b9180ff22a3a',
  'd7afba3c-8495-4707-8462-6629b3a7f89b',
  '4bcae3e3-3392-4676-908f-86db0c8d6472',
  '84b066f7-31a3-4572-a015-21f5defc170e',
  'c849f73e-e097-453e-878d-2af8d9305fd5',
  '3a6a1962-be79-4a1c-98bb-a261e804e0e8',
  '8ed1381b-f342-40ad-acb6-80fdb3c68c1f'
);
UPDATE public.drug_interactions SET evidence_level = 'moderate-evidence', updated_at = now()
WHERE evidence_level = 'title-match' AND id IN (
  '6a933fe1-e46c-4787-9213-3e006b3503d6',
  '4bf5bca5-3f77-4a0d-84ca-14fcd17fb424',
  'ae73bf23-31d9-4dad-91d9-110c245251ea',
  '170bfc0c-62ff-40b3-8d61-062b7c945d56',
  'b9479749-3f42-48fb-bc7c-d023a0ad6677'
);
UPDATE public.drug_interactions SET evidence_level = 'limited-evidence', updated_at = now() WHERE evidence_level = 'title-match';
UPDATE public.drug_interactions SET rxcui = '2344', updated_at = now() WHERE drug_name = 'Chloral Hydrate' AND (rxcui IS NULL OR trim(rxcui) = '');
UPDATE public.drug_interactions SET rxcui = '4511', updated_at = now() WHERE drug_name = 'Folic Acid Supplements' AND (rxcui IS NULL OR trim(rxcui) = '');


-- 4. Replace English em-dashes across 33 monographs with standard punctuation
UPDATE public.herbs SET description = $ed$Aloe succotrina (Asphodelaceae) is a tree aloe endemic to the Cape Peninsula of South Africa, historically classified within Aloe series Purpurascentes and section Anguialoe as confirmed by chemotaxonomic and morphological appraisal (PMID 11336811). The dried leaf exudate, known commercially as Cape aloes, has been traded since antiquity and was historically conflated with Socotran aloes. Its primary bioactive constituent classes include hydroxyanthracene derivatives (principally the anthraquinone glycoside aloin, or barbaloin) together with aloeresins and other phenolic chromones, plus flavonoids. Pharmacologically characterized actions come mainly from preclinical work: in a rat model, A. succotrina extract demonstrated antihyperlipidemic activity, possibly mediated through inhibition of HMG-CoA reductase (PMID 24693447). Clinically, Cape aloe exudate is recognized as a stimulant laxative via hydroxyanthracene glycosides, and topical applications have traditional standing for wounds and skin conditions, though robust human clinical data specific to this species remain limited.$ed$, updated_at = now() WHERE slug = 'aloe-succotrina';
UPDATE public.herbs SET description = $ed$Phyllanthus urinaria (chamber bitter; Meniran) is an annual herb of the family Phyllanthaceae distributed across tropical Asia, Africa, and the Americas, and is ethnobotanically distinguished from its close relative Phyllanthus niruri. The whole plant (leaf, stem, and root) serves as the medicinal drug in most preparations. Its phytochemistry is dominated by lignans (phyllanthin, hypophyllanthin, niranthin), together with hydrolyzable tannins and polyphenols (ellagic acid, corilagin, gallic acid derivatives) and flavonoids such as quercetin. These constituents are associated with antioxidant, anti-inflammatory, and hepatoprotective activity documented in preclinical systems. Pharmacological research, reviewed in peer-reviewed literature, centers on liver disease: preclinical and some clinical work examines effects in viral hepatitis, liver fibrosis and cirrhosis, and hepatocellular carcinoma, with proposed mechanisms including inhibition of hepatic stellate cell activation, antiviral activity against hepatitis B, and modulation of NF-κB, PI3K/AKT, and MAPK signaling. Human clinical evidence remains heterogeneous, consisting of small trials in chronic hepatitis B with inconsistent antiviral outcomes and limited controlled data elsewhere. Traditional systems, particularly in Indonesia (as Meniran), Southeast Asia, and China, employ the plant for liver complaints, urinary disorders, and metabolic conditions. Clinical application should follow the strength of available human evidence, which remains preliminary for most indications.$ed$, updated_at = now() WHERE slug = 'bhumi-amla';
UPDATE public.herbs SET description = $ed$Cassia auriculata (family Fabaceae), commonly known as Tanner's cassia or avaram, is a branched shrub native to South Asia, extensively documented in Ayurvedic and Siddha medical literature. The plant parts used medicinally include flowers, bark, leaves, and roots. Phytochemical characterization identifies phenolic constituents as the dominant bioactive class, including the anthraquinone glycoside cassiaurin, the flavonoids kaempferol and quercetin, the flavan-3-ol catechin, leucocyanidin, and high concentrations of condensed and hydrolysable tannins, historically exploited in leather tanning, from which the common name derives. Verified pharmacological actions documented in peer-reviewed reviews and experimental studies include antidiabetic effects with demonstrated glycemic modulation in animal models, antioxidant activity through radical-scavenging phenolics, antimicrobial activity against bacterial and fungal isolates, and anti-inflammatory activity. A published review (PMID 24163950) consolidates the pharmacological potentials of C. auriculata alongside C. fistula. A subsequent study (PMID 34080203) reports that leaf extract ameliorates diabetic nephropathy in an animal model by attenuating autophagic necroptosis via RIP-1/RIP-3-p-p38MAPK signaling. The clinical scope in humans remains limited; most evidence derives from in vitro and rodent models rather than controlled human trials, and definitive human therapeutic applications are not established by the available literature.$ed$, updated_at = now() WHERE slug = 'cassia-auriculata';
UPDATE public.herbs SET description = $ed$Matricaria chamomilla (synonym Matricaria recutita), German chamomile, is an annual herb of the Asteraceae family whose dried flower heads constitute the pharmacopeial drug Matricariae flos. Its principal bioactive classes include sesquiterpene constituents of the volatile oil, chiefly (-)-α-bisabolol and chamazulene generated from matricin during steam distillation or extraction, alongside flavonoids dominated by apigenin and apigenin-7-O-glucoside, with lesser luteolin and quercetin glycosides. Apigenin binds benzodiazepine receptor sites in vitro, forming the pharmacological rationale for sedative use. Documented pharmacological actions include anti-inflammatory activity via COX/LOX pathway modulation, antispasmodic effects on gastrointestinal smooth muscle attributed to flavonoid and bisabolol fractions, mild anxiolytic activity reported in randomized trials of standardized extract, and topical anti-inflammatory and wound-supporting effects in oral mucositis and atopic dermatitis models. Evidence is strongest for standardized extract in generalized anxiety disorder and for topical application in mucositis; tea-based uses rest on weaker, heterogeneous trial data (reviewed in Srivastava et al., PMID 21132119).$ed$, updated_at = now() WHERE slug = 'chamomile';
UPDATE public.herbs SET description = $ed$Costus speciosus (Koen. ex Retz.) J.E. Sm., synonym Cheilocostus speciosus, family Costaceae, commonly known as crepe ginger, is a perennial rhizomatous herb native to South and Southeast Asia. The rhizome and leaves contain steroidal saponins (diosgenin, dioscin, and gracillin) as principal bioactive constituents, alongside flavonoids such as kaempferol and quercetin. Diosgenin is historically significant as a pharmaceutical precursor for steroidal drug synthesis. Pharmacological investigations, largely preclinical, have documented hypoglycemic, anti-inflammatory, antipyretic, antifungal, and cytotoxic activities in vitro and in animal models. The reviewed literature indexed by the provided citations (PMID 27515456; PMID 40435094) specifically addresses proposed anticancer mechanisms of the plant's active ingredients, including apoptosis induction and modulation of cell signaling pathways, which remain established only at cellular and animal levels. Traditional systems, notably Ayurveda, use rhizomes and leaves for diabetes, fever, constipation, and rheumatic complaints. No adequately powered human clinical trials substantiate efficacy for any indication, so clinical application remains investigational.$ed$, updated_at = now() WHERE slug = 'costus-speciosus';
UPDATE public.herbs SET description = $ed$Cuphea hyssopifolia (syn. C. hyssopifolia Kunth), a small evergreen shrub of the family Lythraceae native to Mexico and Central America, is known horticulturally as Mexican false heather or elfin weed. In Mexican folk medicine the plant has been used as a decoction or infusion for blood sugar reduction, inflammation, and wound management. Phytochemical investigation has identified hydrolyzable tannins as the most distinctive constituent class: four macrocyclic ellagitannins (hyssopifoliins A-D) isolated from aerial parts demonstrated cytotoxic and antitumor activity in vitro, chiefly against murine tumor cell lines. General constituent screening has additionally reported flavonoids, condensed tannins, and phenolic acids. Pharmacological claims such as antidiabetic activity rest primarily on ethnobotanical documentation; no randomized human clinical trials evaluating C. hyssopifolia for glycemic control, inflammation, or any other indication were identified in the verified literature reviewed here. The strongest experimental signal (cytotoxicity of the macrocyclic ellagitannins) derives from cell-culture and murine data only and has not been translated into human oncology studies. Clinical scope is therefore limited to preliminary phytochemical research, with safety, dosing, and efficacy in humans unestablished. Adverse-effect data remain unpublished, and use during pregnancy lacks any formal assessment.$ed$, updated_at = now() WHERE slug = 'cuphea-hyssopifolia';
UPDATE public.herbs SET description = $ed$Curcuma wenyujin Y.H. Chen & C. Ling is a perennial rhizomatous herb of the Zingiberaceae family, native to southeastern China, particularly Zhejiang province, where it is cultivated alongside the closely related species C. longa and C. phaeocaulis. In Chinese materia medica taxonomy, its dried tuber is one botanical source of the drug Yu Jin, while the rhizome is processed as E Zhu, a classified blood-moving herb within the traditional Chinese medicine system. The plant's principal constituent groups are sesquiterpenoid volatile oils (rich in curdione, germacrone, curcumene, and furanodiene) and diarylheptanoids including curcumin, together with ar-turmerone and additional phenolic turmerone derivatives. Documented pharmacological actions in preclinical models include choleretic, anti-inflammatory, antiplatelet, and hepatoprotective effects, consistent with the constituents' known bioactivities. Recent cell and animal research reports CNS-relevant activity: rhizome extract attenuated Alzheimer's-type cognitive deficits and suppressed NLRP3-associated pyroptosis through PINK1/Parkin-mediated autophagy, and rhizome extract ameliorated lipid accumulation in cellular models. Clinical scope remains narrow; controlled human trials specific to C. wenyujin are lacking, and current applications rest on preclinical pharmacology and longstanding traditional use rather than verified clinical efficacy.$ed$, updated_at = now() WHERE slug = 'curcuma-wenyujin';
UPDATE public.herbs SET description = $ed$Dioscorea bulbifera L. (air potato, air yam; family Dioscoreaceae) is a perennial climbing vine distributed throughout tropical Asia and Africa, recognized by aerial bulbils used in ethnobotanical practice. The bulbils and tubers contain furanoterpenoid diterpenoids (notably the diosbulbins A-D), steroidal saponins including diosgenin and related sapogenins, polyphenols, and norclerodane diterpenoids. Pharmacological investigations, including the extensive review in PMID 38265372, describe antimicrobial, antioxidant, anti-inflammatory, and antitumor activities demonstrated largely in vitro and in animal models, alongside documented applicability in nanoparticle synthesis. However, the species presents a clinically significant safety concern: furanoterpenoids undergo metabolic activation to reactive intermediates, and a comprehensive safety review (PMID 32757959) documents hepatotoxicity attributable to bioactivation of these compounds. Accordingly, clinical scope is constrained: D. bulbifera is best characterized as a chemically diverse but hepatotoxicity-prone botanical whose therapeutic applications in humans remain unestablished by controlled clinical trials, and whose uncultivated varieties carry documented liver injury risk.$ed$, updated_at = now() WHERE slug = 'dioscorea-bulbifera';
UPDATE public.herbs SET description = $ed$Echinacea purpurea (L.) Moench is a perennial herb of the Asteraceae (daisy) family, native to central and eastern North America, with a genus comprising nine accepted species, of which E. purpurea, E. angustifolia, and E. pallida are most used therapeutically. Three constituent classes dominate its pharmacology: lipophilic alkamides (mainly alkylamides of isobutylamide structure) concentrated in roots and seed, polar caffeic acid derivatives (particularly cichoric acid in E. purpurea, and echinacoside in E. angustifolia and E. pallida), and high-molecular-weight polysaccharides and glycoproteins. Documented pharmacological actions include modulation of innate immune signaling, including effects on cytokine production and phagocytic activity, plus in vitro anti-inflammatory and antiviral activity against respiratory viruses. Clinically, E. purpurea preparations have been evaluated principally for prevention and treatment of the common cold and upper respiratory tract infections; systematic review evidence indicates modest, formulation-dependent reductions in cold recurrence and duration, consistent with the two cited systematic reviews and meta-analyses. Evidence for other indications remains limited.$ed$, updated_at = now() WHERE slug = 'echinacea';
UPDATE public.herbs SET description = $ed$Rhodiola crenulata (Fu Zi Hong Jing Tian) is a high-altitude Crassulaceae species native to the Tibetan Plateau and southwestern China, botanically distinct from Rhodiola rosea despite frequent commercial substitution. The rooted rhizome contains phenylpropanoid glycosides (principally salidroside, the marker compound used for standardization) together with crenulin, tyrosol, flavonoids, and organic acids; the rosavin fraction characteristic of R. rosea is typically lower or absent, informing pharmacological and quality-control differentiation. In Tibetan Sowa Rigpa medicine, the plant has documented traditional application for hypoxia-related disorders, fatigue, and cardiovascular complaints at altitude. Contemporary pharmacological research, including a 2024 preclinical study, demonstrates protection against hypobaric hypoxia-induced brain injury via preservation of blood-brain barrier integrity and modulation of cerebral energy metabolism. Clinical evidence specific to R. crenulata in humans remains limited; adaptogenic, cardioprotective, and anti-fatigue categorizations derive largely from related Rhodiola species research and should be interpreted with species-level caution.$ed$, updated_at = now() WHERE slug = 'fu-zi-hong-jing-tian';
UPDATE public.herbs SET description = $ed$Gentiana acaulis (stemless gentian; Gentianaceae) is a perennial alpine herb native to European mountain ranges, characterized by a basal rosette of lanceolate leaves and large solitary sky-blue trumpet-shaped flowers. Taxonomically it belongs to Gentiana section Ciminalis, where leaf micromorphology has been applied to species delimitation in Balkan representatives (PMID 41095119). The pharmacologically relevant organs are the roots and rhizome, which contain secoiridoid glycosides (principally gentiopicroside and amarogentin, the latter among the most bitter natural substances known) together with swertiamarin, flavonoids, and tannins. These constituents account for the classical bitter (amarum) activity: stimulation of bitter taste receptors with reflexive augmentation of salivary, gastric, and biliary secretions, the basis of its use as a digestive bitter tonic. Traditional and modern phytotherapy applications span appetite stimulation, dyspepsia, and hepatobiliary support, though high-quality human clinical trials specific to Gentiana acaulis are lacking; evidence derives largely from the gentian root pharmacopoeial class. Field studies have additionally documented its mycorrhizal associations in Swiss montane meadows (PMID 17630317), relevant to ecology rather than therapeutics. Clinically it remains a narrow-spectrum bitter agent with undefined evidence depth.$ed$, updated_at = now() WHERE slug = 'gentiana-acaulis';
UPDATE public.herbs SET description = $ed$Ginger (Zingiber officinale Roscoe) is a perennial herb of the family Zingiberaceae cultivated for its underground rhizome, which serves as both a culinary spice and a pharmacological agent. The rhizome contains pungent phenolic ketones (principally the gingerols, of which 6-gingerol is the most abundant in fresh tissue) that undergo thermal degradation or dehydration to shogaols, with subsequent conversion to zingerone. These constituents, alongside volatile oil components such as zingiberene, constitute the primary bioactive classes. Documented pharmacological actions include 5-HT3 and cholinergic-mediated antiemetic activity, inhibition of prostaglandin and leukotriene synthesis relevant to anti-inflammatory effects, and gastric prokinetic activity accelerating gastric emptying. Clinical research has most extensively examined ginger for nausea of various etiologies and for painful osteoarthritis; a systematic review of osteoarthritis evidence has evaluated randomized trial data in that indication (PMID 25230520). The scope of validated clinical application remains narrower than the breadth of its traditional corpus, which spans multiple medical systems over millennia. Composition varies substantially with cultivar, harvest maturity, and processing, since dried and heat-treated preparations shift the gingerol-shogaol ratio. Dried form of ginger used in TCM (more warming and less dispersing than fresh ginger, Sheng Jiang) is prepared specifically for cold in the middle burner. Red ginger variety with higher essential oil content than common ginger is used in Jamu for circulation and immunity.$ed$, updated_at = now() WHERE slug = 'ginger';
UPDATE public.herbs SET description = $ed$Crataegus laevigata (syn. Crataegus oxyacantha), a Rosaceae tree native to Europe, yields leaf and flower preparations pharmacologically distinct from its fruit. The aerial parts contain flavonoid glycosides (hyperoside, rutin, vitexin, and vitexin-2'-rhamnoside) alongside oligomeric procyanidins, which collectively define the standardization criteria used in regulatory monographs. Compared with hawthorn berry, leaf and flower extracts exhibit higher flavonoid concentrations, making this preparation the preferred form in formal therapeutic assessment. Documented pharmacological actions include dose-dependent positive inotropic effects via inhibition of cAMP phosphodiesterase, enhanced coronary artery dilatation, and mild ACE-inhibition-related blood pressure reduction, mechanisms attributed primarily to procyanidins and flavonoids. Clinical scope has centered on declining cardiac performance corresponding to New York Heart Association functional classes I-II, where standardized extracts have been evaluated in randomized human trials, and on mild hypertension, for which trial data are more limited. Regulatory monographs from Germany's Commission E and ESCOP have historically recognized leaf and flower preparations for mild cardiac insufficiency, distinguishing evidence-based cardiac use from broader traditional cardiovascular applications. Effects typically emerge after several weeks of continuous administration; clinical endpoints remain restricted to mild cardiac conditions rather than severe heart failure management.$ed$, updated_at = now() WHERE slug = 'hawthorn-leaf-flower';
UPDATE public.herbs SET description = $ed$Zingiber mioga (Thunb.) Roscoe, family Zingiberaceae, is a perennial herb native to Japan and East Asia, cultivated primarily for its immature flower buds and young shoots, which are consumed as a seasonal vegetable. Unlike common ginger, the rhizome is not the principal edible organ. Phytochemical characterization of the species has identified diarylheptanoid and ginger-related phenolic constituents, including myogadial (galanal-type compounds), myogaenol, and members of the gingerol/shogaol series, alongside water-soluble polysaccharides isolated from leaf biomass. In vitro analysis of ultrasonic-microwave-extracted leaf polysaccharides demonstrated antioxidant activity and anticoagulant potential (PMID 38091742), though these findings have not been translated into human trials. Genomic resources include a characterized chloroplast genome (PMID 33659662), supporting taxonomic and authentication research. Clinical scope remains narrow: no randomized controlled trials evaluating therapeutic effects in humans were identified in the available literature; evidence is limited to constituent characterization and in vitro pharmacology.$ed$, updated_at = now() WHERE slug = 'japanese-myoga-ginger';
UPDATE public.herbs SET description = $ed$Juniperus sabina L. (savine or savin juniper) is a low-growing, evergreen coniferous shrub of the family Cupressaceae, native to mountainous regions of central and southern Europe and western Asia. Its scale-like leaves and terminal branch tips accumulate a volatile oil rich in monoterpenes, notably sabinyl acetate, sabinene, and the neurotoxic ketones α-thujone and β-thujone. The plant is also documented as a notable botanical source of podophyllotoxin, an aryltetralin lignan concentrated in leaves and dwarf shoots, alongside related lignans and diterpenes. Verified in vitro pharmacological activity includes acetylcholinesterase inhibition associated with podophyllotoxin-containing fractions, together with antimicrobial and insecticidal properties attributable to the essential oil. Because sabinene oil and thujone content confer substantial systemic toxicity (documented historically with nephrotoxicity, hepatotoxicity, convulsions, and fatalities), the species is classified as unsafe for internal therapeutic use; contemporary relevance is limited to toxicology, phytochemical research, and strictly controlled external or veterinary contexts.$ed$, updated_at = now() WHERE slug = 'juniperus-sabina';
UPDATE public.herbs SET description = $ed$Melissa officinalis (lemon balm) is a perennial herbaceous plant in the Lamiaceae (mint) family, characterized by opposite, ovate, toothed leaves that emit a distinct lemon aroma when crushed due to volatile terpene content. Primary bioactive constituent classes include a volatile oil fraction composed predominantly of monoterpene aldehydes (citral isomers, citronellal), phenolic acids (principally rosmarinic acid), and flavonoids such as luteolin and quercetin glycosides. Documented pharmacological actions in preclinical and clinical literature include mild anxiolytic effects, sedative activity, antiviral activity against herpes simplex virus in topical applications, and cognitive effects observed in a small number of controlled trials. The verified clinical scope is limited: a published clinical evidence review (PMID 15272110) addresses lemon balm's use for anxiety and sleep. Evidence for other proposed applications, including digestive and cognitive endpoints in healthy adults, is preliminary and based on small trials. Safety characterization in the provided citation is limited to the anxiety and sleep context; no verified contraindication profile, dosing standard, or adverse-event dataset is established by the available citation. Melissa officinalis (Lamiaceae) is an aromatic perennial herb; the tropical form described as 'Toronjil' is naturalized in Latin America, where it is botanically consistent with the species' essential-oil-bearing foliar chemistry. Primary bioactive constituent classes include a volatile oil dominated by monoterpene aldehydes (citral isomers, geranial/neral), monoterpene alcohols (geraniol), phenolic acids (notably rosmarinic acid), and flavonoids including luteolin and apigenin. Reported pharmacological actions in preclinical and human-experimental literature encompass central nervous system depressant (sedative/anxiolytic-type) effects, antispasmodic activity on smooth muscle, and in-vitro antiviral and antioxidant activity attributable largely to rosmarinic acid and citral fractions. A controlled human investigation referenced in the 3rd IPLeiria International Health Congress proceedings (PMID: 27409075) contributes to the limited clinical dataset on Melissa officinalis administration. Clinical scope remains concentrated on short-term use for mood-state parameters, stress modulation, and mild gastrointestinal spasm; larger definitive trials are lacking. Traditional Latin American and Caribbean applications (anxiety, digestive complaints, fever) are documented ethnobotanically but do not constitute clinical evidence. Preparations typically exploit water-soluble phenolic and volatile components. Taller southern European lemon balm variety with higher rosmarinic acid content has also been used in folk medicine for thyroid and nervous conditions.$ed$, updated_at = now() WHERE slug = 'lemon-balm';
UPDATE public.herbs SET description = $ed$Malva sylvestris (common mallow), a member of the Malvaceae family, is an herbaceous biennial or perennial native to Europe, North Africa, and Western Asia, naturalized widely across temperate regions. Its leaves and flowers are characterized by high mucilage content (polysaccharide-rich fractions comprising rhamnogalacturonans, arabinogalactans, and glucans) which form a demulcent layer over mucous membranes in vitro and are considered primary contributors to the soothing effects observed in traditional pharyngeal and gastrointestinal preparations. Secondary metabolite classes include anthocyanins (notably malvidin-3-glucoside/malvin and malvidin-3,5-diglucoside), flavonoids (including gossypetin and quercetin glycosides), phenolic acids, tannins, and trace terpenoids. Two peer-reviewed reviews document in vitro and animal-model evidence for anti-inflammatory, antioxidant, antimicrobial, and antinociceptive activities, and note demulcent and emollient use consistent with monograph traditions such as ESCOP and EMA herbal monographs on Malva sylvestris folium/flos. Clinical scope in humans remains narrow: controlled human trials specifically isolating M. sylvestris are sparse, and pharmacological claims derive predominantly from preclinical data and traditional documentation. The herb is accordingly positioned as a traditional demulcent agent rather than an evidence-graded therapeutic, pending human pharmacokinetic and clinical outcome data.$ed$, updated_at = now() WHERE slug = 'mallow';
UPDATE public.herbs SET description = $ed$Artemisia vulgaris (European mugwort) is an aromatic perennial herb of the Asteraceae family, widespread across Europe, Asia, and North Africa. Its principal bioactive constituent classes include a volatile oil rich in monoterpenes and sesquiterpenes (notably thujone, 1,8-cineole, and camphor) alongside flavonoids, coumarins, sesquiterpene lactones, and only trace quantities of artemisinin. Phytochemical and pharmacological reviews document in vitro and animal-data antimicrobial, antioxidant, antispasmodic, anti-inflammatory, and anthelmintic activities for leaf extracts and essential oil preparations. In European herbal practice the bitter leaf has been used as a digestive bitter and in Traditional Chinese and Japanese medicine as the processed base material (moxa) for moxibustion, in which dried leaf is burned near or on acupuncture points. Contemporary clinical scope is narrow: the herb is chiefly used as a bitter tincture and topical or ritual emmenagogue, while its thujone content imposes well-recognized toxicity considerations in epilepsy and pregnancy. Comprehensive pharmacological characterizations exist, but rigorous randomized human clinical trials are scarce, and most asserted therapeutic actions therefore remain preliminary rather than evidence-graded.$ed$, updated_at = now() WHERE slug = 'mugwort-european';
UPDATE public.herbs SET description = $ed$Artemisia indica Willd. is an aromatic perennial herb of the Asteraceae family, distributed across South and Southeast Asia, where it has been incorporated into Ayurvedic and Indonesian Jamu materia medica. It belongs to a morphologically complex taxonomic group closely allied to Artemisia vulgaris, and the aerial parts (leaves and flowering tops) are the portions most commonly prepared medicinally. The plant accumulates a volatile-oil fraction containing thujone, camphor, and 1,8-cineole as principal monoterpenoids; sesquiterpene lactones of the artemisinin type and flavonoids have also been reported. Published research includes a study reporting metabolic and antioxidant modulation by aqueous extract in a model of glucose and cholesterol dysregulation (PMID 41516183), and a separate study examining root-associated microbiome interactions affecting arsenic tolerance in Artemisia species (PMID 37290353). Human clinical trial data for A. indica are lacking in the available literature. The verified pharmacological scope is therefore limited to phytochemical characterization and preclinical metabolic and antioxidant observations; traditional emmenagogue, digestive, and antimicrobial applications remain ethnobotanical rather than evidence-validated. Constituents such as thujone carry recognized toxicity concerns at elevated exposures, and clinical adverse-effect or dosing data are not established by the cited studies.$ed$, updated_at = now() WHERE slug = 'mugwort-indian';
UPDATE public.herbs SET description = $ed$Passionflower (Passiflora incarnata L.) is a perennial climbing vine of the family Passifloraceae, native to the southeastern United States and naturalized elsewhere. Its aerial parts are the pharmacopeial material, yielding a major class of flavonoid constituents (principally vitexin, isovitexin, orientin, apigenin, and chrysin) together with trace indole alkaloids and compounds structurally associated with GABAergic activity. Pharmacological research attributes the plant's effects primarily to modulation of GABAergic neurotransmission, with the German Commission E approving its use for nervous restlessness. The clinical evidence base is centered on a published randomized trial (PMID 11679026) in which a passionflower extract was evaluated for generalized anxiety disorder; however, the overall trial literature remains of limited volume and modest methodological rigor. In European phytomedicine it is formulated for anxiety-related indications and sleep disturbance, positioning passionflower as a botanical anxiolytic candidate rather than a substantiated treatment across a broad range of conditions. Native passionflower from South American highlands is also traditionally used for anxiety, insomnia, and nervous conditions.$ed$, updated_at = now() WHERE slug = 'passionflower';
UPDATE public.herbs SET description = $ed$Peppermint (Mentha x piperita) is a sterile hybrid perennial herb in the Lamiaceae family, resulting from the cross of watermint (Mentha aquatica) and spearmint (Mentha spicata). It is cultivated widely across temperate regions for food, cosmetic, and medicinal applications. Its principal bioactive constituents are volatile monoterpenes (menthol, menthone, and menthyl acetate) alongside phenolic compounds including rosmarinic acid and the flavonoid luteolin. The essential oil, typically obtained by steam distillation of flowering aerial parts, is the most clinically studied preparation. Documented pharmacological actions include smooth-muscle relaxation attributed primarily to menthol's calcium-channel modulation, carminative and antispasmodic effects on gastrointestinal tissue, and topical counterirritant and cooling activity. The strongest clinical evidence base concerns enteric-coated peppermint oil in irritable bowel syndrome, where randomized trials and systematic reviews demonstrate symptom reduction. Additional investigated indications include functional dyspepsia, tension-type headache applied topically, and relief of nausea, though evidence quality varies. Peppermint remains among the most thoroughly researched essential-oil therapies in modern phytomedicine, with standardized oil preparations available in regulated pharmaceutical forms. Peppermint Spanish (Mentha x piperita var. citrata) is a citrus-scented infraspecific hybrid of the Mentha piperita complex, classified within the Lamiaceae family. Its essential oil profile differs markedly from classic peppermint: linalool and linalyl acetate dominate, with only trace menthol and the coumarin bergapten, yielding characterization closer to bergamot-mint than menthol-dominant chemotypes. Documented pharmacological activity of the volatile constituents includes in vitro antifungal effects, with linalool and linalyl acetate showing anti-inflammatory and anxiolytic-relevant activity in preclinical research. Primary research on this variety concerns terpene production in Agrobacterium-transformed shoot cultures of M. citrata, confirming biosynthetic capacity for monoterpene accumulation. Clinically, the herb is positioned as a gentler aromatic carminative relative to standard peppermint, used predominantly at culinary and aromatherapy exposure levels; robust human clinical trials specific to this variety are lacking, and its therapeutic scope remains chiefly traditional and preclinical.$ed$, updated_at = now() WHERE slug = 'peppermint';
UPDATE public.herbs SET description = $ed$Wolfiporia cocos (syn. Poria cocos), a wood-decay polypore fungus (Polyporaceae), forms a subterranean sclerotium on pine roots, historically termed 'fu ling' in Chinese materia medica. The dried sclerotium contains primarily water-soluble polysaccharides (pachyman, a β-(1→3)-glucan-rich fraction) and lanostane-type triterpenoid acids, notably pachymic acid, dehydropachymic acid, and polyporenic acid, along with sterols including ergosterol derivatives. Published pharmacological reviews attribute anti-inflammatory, immunomodulatory, diuretic, sedative-hypnotic, and cytotoxic-to-tumor-cell-line activity mainly to in vitro and animal models; polysaccharide fractions stimulate macrophage and lymphocyte function experimentally. Human clinical data remain sparse, so the clinical scope is confined to its long-standing role as a component of traditional multi-herb decoctions and a generally well-tolerated food-grade ingredient, rather than an evidence-based monotherapy. Reported applications (edema, insomnia, anxiety, and spleen or digestive complaints) derive from traditional documentation and preclinical research rather than adequately powered controlled human trials.$ed$, updated_at = now() WHERE slug = 'poria-cocos';
UPDATE public.herbs SET description = $ed$Wolfiporia extensa (synonym Poria cocos; Fu Ling) is a wood-decay polypore fungus in the family Polyporaceae, whose sclerotium is a documented material in traditional East Asian materia medica. Poria Cocos Skin (Fu Ling Pi) refers specifically to the brown outer peridium layer of the sclerotium, separated from the white inner tissue during processing. Its principal characterized constituents include triterpene acids (notably pachymic acid, tumulosic acid, and polyporenic acid C) alongside polysaccharide fractions rich in beta-glucans; monosaccharide profiling studies confirm tissue-specific compositional differences between the outer skin and inner flesh. Pharmacological investigations of triterpene-rich fractions report diuretic and anti-inflammatory activity in preclinical models, consistent with the skin layer's traditional differentiation from the inner sclerotium for edema-related applications. Human clinical trial evidence remains limited; current clinical scope is therefore defined primarily by traditional documentation and preclinical data rather than verified human efficacy studies, and standardized clinical dosing remains unestablished.$ed$, updated_at = now() WHERE slug = 'poria-cocos-skin';
UPDATE public.herbs SET description = $ed$Origanum onites (Pot Marjoram) is a perennial herb in the Lamiaceae family, native to the eastern Mediterranean, including Greece, Turkey, and the Balkans. Taxonomically, it is closely allied to Origanum vulgare and Origanum majorana, occupying an intermediate position in flavor and chemical composition. Its primary bioactive constituents are monoterpenoid phenols (chiefly carvacrol and thymol) within a volatile oil fraction, alongside phenolic acids such as rosmarinic acid and assorted flavonoids. Published phytochemical and pharmacological review literature on this species documents in vitro and ex vivo antimicrobial activity of the essential oil, antioxidant activity attributable to phenolic constituents, and anti-inflammatory actions reported in laboratory models. Clinical scope in humans remains narrow: published primary-source material consists largely of phytochemical characterization and formulation studies, with no robust randomized controlled trials establishing specific therapeutic indications. O. onites remains primarily a culinary and ethnobotanical species, with human clinical efficacy currently unestablished.$ed$, updated_at = now() WHERE slug = 'pot-marjoram';
UPDATE public.herbs SET description = $ed$Schisandra sphenanthera (Chinese wu wei zi nan, southern schisandra) is a deciduous woody vine of the family Schisandraceae, native to central and southern China, whose dried fruit is used in traditional Chinese medicine. It is botanically and phytochemically related to Schisandra chinensis (northern schisandra) but is distinguished by a different lignan profile. Its principal bioactive constituent classes are dibenzocyclooctadiene lignans (notably schisantherin A, schisantherin B, schisandrin, and schisanhenol) along with polysaccharides, triterpenoids, and volatile constituents. The fruit is conventionally characterized as possessing all five classical flavors (sour, pungent, bitter, salty, sweet). Published pharmacological research, primarily preclinical and reviewed in peer-reviewed literature, documents hepatoprotective, antioxidant, anti-inflammatory, and immunomodulatory activities, with lignans such as schisantherin attributed to liver-protective effects and polysaccharides associated with immunomodulatory properties. Human clinical investigation remains limited compared with S. chinensis; the evidence base for therapeutic use in humans derives mainly from traditional practice, in vitro, and animal studies. Its documented TCM applications include chronic cough, liver-related disorders, and fatigue.$ed$, updated_at = now() WHERE slug = 'schisandra-sphenanthera';
UPDATE public.herbs SET description = $ed$Asparagus racemosus (family Asparagaceae), known in Ayurvedic medicine as Shatavari, is a woody climbing perennial indigenous to the Indian subcontinent, Nepal, Sri Lanka, and parts of Southeast Asia and Africa. The medicinal material is the tuberous root/rhizome, which has been characterized chemically as containing steroidal saponins (principally the shatavarins I–IV) alongside isoflavones, asparagamine A, flavonoids, polysaccharides, and free amino acids. Reviews of preclinical literature (e.g., PMID 14515032 and 2022 nutritional profiling research at PMID 36433663) document in-vitro and animal-model activity including phytoestrogenic effects, galactagogue activity, antioxidant, anti-inflammatory, immunomodulatory, gastroprotective, and adaptogenic properties. In Ayurvedic practice the root is classified as a rasayana (rejuvenative) and is traditionally applied to female reproductive health, lactation, and inflammatory conditions. Modern clinical investigation remains limited: existing human trials are few, small, and methodologically constrained, predominantly evaluating galactagogue use in lactating women. Consequently, its clinical scope is best described as a phytoestrogenic, saponin-bearing botanical whose pharmacology is largely established preclinically, with uncertain transposition to human therapeutic outcomes pending larger, well-controlled trials.$ed$, updated_at = now() WHERE slug = 'shatavari-tonic';
UPDATE public.herbs SET description = $ed$Monarda punctata (Lamiaceae), commonly known as spotted bee balm or horsemint, is a North American aromatic herb in the mint family characterized by whorled, bracteate inflorescences with spotted, yellowish-purple flowers. Its primary bioactive constituent class is the volatile oil, which is notably rich in phenolic monoterpenes (particularly thymol and carvacrol) alongside limonene and beta-myrcene; chemotype variation across populations significantly influences this oil composition. Flavonoids and other phenolic compounds are also present. The essential oil demonstrates documented antioxidant and antimicrobial activity in vitro, consistent with its high thymol/carvacrol content, and the herb has historically been used as an antipyretic, respiratory remedy, carminative, and diaphoretic. Clinical scope in humans is currently unsupported by controlled trials; evidence remains confined to phytochemical characterization, antimicrobial susceptibility assays, and antioxidant testing. Traditional external application to wounds reflects the antiseptic potential of its topical volatile constituents.$ed$, updated_at = now() WHERE slug = 'spotted-bee-balm';
UPDATE public.herbs SET description = $ed$Ligusticum striatum DC. (syn. L. chuanxiong), family Apiaceae, is the plant producing the rhizome known in traditional Chinese medicine as Chuanxiong. The drug is an aromatic, irregularly nodose dried rhizome with a characteristic strong aroma and pungent, slightly bitter taste. Its principal bioactive classes are phthalide compounds (most notably ligustilide, senkyunolide families, and butylphthalide derivatives), alkaloids including tetramethylpyrazine (ligustrazine), and phenolic acids such as ferulic acid, which coexist in volatile oil and aqueous fractions. Documented pharmacological actions include antiplatelet activity, vasodilation, calcium-channel modulation, analgesic effects, and anti-inflammatory activity, demonstrated primarily in experimental systems and pharmacological reviews. Tetramethylpyrazine is an approved pharmaceutical agent in China for cerebrovascular and cardiovascular indications, administered parenterally. The whole plant is most extensively used in East Asian medicine for circulatory and headache-related conditions. Clinical research on the botanical extract itself remains limited relative to isolated constituents, and evidence quality varies markedly. The rhizome is commonly evaluated for headache management and circulatory disorders, but rigorous large-scale human trials establishing efficacy for these uses are insufficient.$ed$, updated_at = now() WHERE slug = 'szechuan-lovage';
UPDATE public.herbs SET description = $ed$Angelica acutiloba (syn. Ligusticum acutilobum; Japanese toki, Chinese du huo/dang gui relative) is a perennial member of the Apiaceae family cultivated in Japan and Taiwan and used extensively in Kampo medicine. The dried root is the medicinal organ, characterized by a distinct aromatic odor attributable to volatile phthalide compounds, principally ligustilide and senkyunolide derivatives, alongside ferulic acid and immunologically active polysaccharides. Pharmacologically documented actions include antispasmodic effects on smooth muscle, anti-inflammatory activity through modulation of inflammatory signaling pathways, and, per a 2023 in vitro study citing PMID 37907950, induction of A549 lung cancer cell pyroptosis via the NF-κB/NLRP3 pathway, an observation confined to cell culture with no human translation. Population-genetic research (PMID 37581741) has clarified taxonomic boundaries between A. acutiloba, the variety iwatensis, and their natural hybrids using chloroplast DNA and MIG-seq SNP markers, relevant to botanical authentication and quality control. Clinical scope in contemporary practice rests largely on traditional Kampo frameworks, notably its role as a blood-moving tonic in multi-herb formulas such as Toki-shakuyaku-san; standalone randomized human trial evidence remains sparse and should not be presumed.$ed$, updated_at = now() WHERE slug = 'taiwanese-angelica';
UPDATE public.herbs SET description = $ed$Juniperus recurva (Himalayan/Tibetan juniper, Cupressaceae) is a montane conifer of the Tibetan plateau and Himalayan region, historically significant in Sowa Rigpa (Tibetan medicine). Its principal bioactive constituents are volatile oil components (monoterpenes such as alpha-pinene) and diterpenoid phenols including ferruginol and cedrol, characterized in essential oil analysis of the leafy twigs and berries (PMID 17265267). Taxonomically, the species is closely related to Juniperus squamata, whose chloroplast genome has been sequenced, clarifying its phylogenetic placement among Asian montane Cupressaceae (PMID 33365443). Pharmacological scope is limited: in vitro and essential oil studies suggest antimicrobial potential attributable to terpene content, and traditional systems classify the plant as diuretic and expectorant. No large human clinical trials have been identified for this species in the published literature. Clinical applications considered by practitioners pertain to respiratory complaints and external or internal use as an aromatic diuretic, though these indications rest primarily on ethnobotanical precedent rather than controlled human evidence. Dosage, contraindication, and adverse effect parameters are not established by the available peer-reviewed citations and should not be assumed from related Juniperus species without verification.$ed$, updated_at = now() WHERE slug = 'tibetan-juniper';
UPDATE public.herbs SET description = $ed$Turmeric (Curcuma longa) is a rhizomatous perennial herb of the Zingiberaceae family, cultivated widely across South and Southeast Asia. Its rhizome is a source of curcuminoids, principally curcumin, demethoxycurcumin, and bisdemethoxycurcumin, a class of diarylheptanoid polyphenols responsible for the rhizome's characteristic yellow pigmentation. The volatile oil fraction contains sesquiterpenes including turmerone, ar-turmerone, and atlantone. Curcumin exhibits documented anti-inflammatory and antioxidant activity in preclinical and human studies, with proposed mechanisms including modulation of inflammatory signaling pathways. Clinically, systematic reviews have evaluated standardized curcuminoid extracts for osteoarthritis and other arthritic conditions, and randomized controlled trials have examined curcumin supplementation in major depression; human pharmacokinetic research demonstrates curcumin's inherently low oral bioavailability, motivating formulation strategies such as piperine co-administration and phospholipid or micellar delivery systems. The evidence base is heterogeneous, with study quality, extract standardization, and dose varying substantially across trials. Curcumin should be understood as a bioactive compound with defined investigational applications rather than a general-purpose health intervention. Turmeric variety grown in Okinawa is used in local folk medicine for liver support and longevity, and a Polynesian variety has been used in Tongan traditional medicine for anti-inflammatory and digestive conditions. Curcuma longa (Zingiberaceae) rhizome extracts standardized to concentrated curcuminoids (curcumin, demethoxycurcumin, bisdemethoxycurcumin) reach levels far exceeding the 3–5% content of the dried rhizome. Curcumin exhibits documented anti-inflammatory, antioxidant, and anti-amyloid activities in preclinical models, with proposed mechanisms including modulation of NF-κB, COX-2, and cytokine signaling. Because unconjugated curcumin has low oral bioavailability, commercial preparations employ phospholipid complexation, nanoparticle carriers, or co-administration with piperine. Clinical evaluation is most substantiated in osteoarthritis: two systematic reviews and meta-analyses of randomized controlled trials (PMID 35935936; PMID 34017975) report evidence for symptomatic benefit in knee and other osteoarthritis populations, with efficacy comparable to nonsteroidal anti-inflammatory drugs in some trials. The metabolic fate of curcumin is complex, with extensive glucuronidation and reduction; circulating parent compound concentrations remain low without absorption-enhancing formulations. Clinical scope is accordingly narrow: analgesic and functional benefit in osteoarthritis is the best-supported indication, whereas neuroprotective and broad systemic anti-inflammatory claims lack comparable human trial support.$ed$, updated_at = now() WHERE slug = 'turmeric';
UPDATE public.herbs SET description = $ed$Valeriana jatamansi (syn. V. wallichii), family Caprifoliaceae (formerly Valerianaceae), is a perennial herbaceous plant native to the Himalayan region, whose rhizome and roots constitute the medicinal drug known in Ayurvedic materia medica as Tagara or Indian valerian. The drug is chemically characterized by an essential oil rich in sesquiterpenoids (including jatamansone/valeranone, valerenane-type, and vetiselinane-type compounds) alongside iridoids (valepotriates), alkaloids, and short-chain carboxylic acids such as isovaleric acid. Documented pharmacological activities reported in systematic reviews of the literature include sedative–hypnotic, anxiolytic, anticonvulsant, antispasmodic, and neuroprotective effects, attributed largely to GABAergic modulation by sesquiterpene and valepotriate fractions. Traditional and integrative texts describe its application to sleep disturbances, anxiety disorders, and nervous conditions. However, the human clinical evidence base remains substantially thinner than for European Valeriana officinalis, with most pharmacological findings derived from in vitro, rodent and preclinical studies, so clinical scope should be interpreted cautiously pending controlled human trials.$ed$, updated_at = now() WHERE slug = 'valeriana-jatamansi';
UPDATE public.herbs SET description = $ed$Salvia apiana (white sage), family Lamiaceae, is an aromatic evergreen shrub native to the southwestern United States and northwestern Mexico. The leaves contain a volatile oil rich in monoterpene oxides and ketones (chiefly 1,8-cineole and camphor with measurable alpha-pinene) alongside abietane-type diterpenoids and phenolic acids, notably rosmarinic acid, as characterized by phytochemical profiling (PMID 28025900) and transcriptomic and metabolomic analysis identifying diterpenoid and phenolic acid biosynthetic pathways (PMID 35755672). In vitro research on these constituents and extracts documents antimicrobial and antioxidant activity, and rosmarinic acid is a well-characterized polyphenol studied for anti-inflammatory properties. The clinical scope of S. apiana itself remains narrow: pharmacological conclusions rest primarily on in vitro and constituent-level data rather than human trials of the whole plant. Ethnobotanically, the plant holds ceremonial importance in Native American smudging practices, and decoctions have been applied traditionally to respiratory and digestive complaints. Verified human clinical dosage, contraindication, and adverse-effect profiles remain unestablished in primary clinical literature.$ed$, updated_at = now() WHERE slug = 'white-sage';

-- 5. Fix French grammar, machine-translation artifacts, and truncated descriptions (9 herbs)
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fr${"name": "Myrtille", "description": "La myrtille européenne (Vaccinium myrtillus) est une petite baie bleu foncé apparentée à l'airelle, originaire d'Europe. Elle est utilisée en phytothérapie depuis le Moyen Âge et a gagné en notoriété durant la Seconde Guerre mondiale lorsque des pilotes de la RAF auraient consommé de la confiture de myrtille avant des missions nocturnes pour soutenir leur vision. Elle est particulièrement riche en anthocyanosides.", "common_names": ["Myrtille européenne", "Airelle myrtille", "Brimbelle", "Bluets d'Europe"], "modern_uses": ["Santé oculaire et fonction visuelle", "Rétinopathie diabétique", "Troubles circulatoires", "Insuffisance veineuse chronique", "Soutien dans la dégénérescence maculaire"], "dosage_child": "Sans danger comme aliment ; pour les extraits chez l'enfant de 6 à 12 ans, utiliser la moitié de la dose adulte sous avis professionnel", "side_effects": ["Troubles digestifs légers", "Vertiges", "Maux de tête", "Léger effet fluidifiant sanguin"]}$fr$::jsonb, true), updated_at = now() WHERE slug = 'bilberry';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fr${"description": "Momordica charantia (la margose ou melon amer), membre de la famille des Cucurbitacées, est une liane grimpante cultivée dans les régions tropicales d'Asie, d'Afrique et des Amériques. Ses fruits, ses graines et ses feuilles présentent un profil phytochimique caractéristique comprenant la charantine (mélange de glycosides stéroïdiens composé de glucoside de sitostérol et de glucoside de stigmastérol), le polypeptide-P (protéine insulino-mimétique de 166 résidus isolée du fruit et des graines), la vicine, des triterpénoïdes de type cucurbitane (dont la momordicine et les momordicosides) ainsi que des alcaloïdes. Les actions pharmacologiques documentées dans les travaux mécanistiques et précliniques incluent une activité insulino-mimétique, l'inhibition de l'absorption intestinale du glucose, la stimulation de son utilisation périphérique, l'activation de l'AMPK dans le muscle squelettique et le tissu adipeux et des effets protecteurs sur les cellules bêta. Une revue de 2022 publiée dans Food Chemistry (PMID 35408574) synthétise cette bioactivité antidiabétique, tandis que les essais cliniques humains sur la glycémie demeurent hétérogènes. L'entrée inclut également les variétés sauvages des Caraïbes employées en tisane et le Melão de São Caetano (Momordica charantia var. abbreviata Ser.) du Brésil, caractérisé en chimie analytique et in vitro (PMID 31151277; PMID 32784816) sans essai clinique établissant d'efficacité ou de posologie thérapeutique chez l'humain."}$fr$::jsonb, true), updated_at = now() WHERE slug = 'bitter-melon-metabolic';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fr${"modern_uses": ["Expectorant", "Sédatif léger", "Anti-inflammatoire"], "common_names": ["Coucou", "Primevère vraie", "Herbe de saint Pierre"]}$fr$::jsonb, true), updated_at = now() WHERE slug = 'cowslip';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fr${"description": "Le galéga officinal (Galega officinalis) est une herbacée vivace de la famille des Fabacées, originaire d'Europe, où il est utilisé comme remède à base de plantes depuis le Moyen Âge. Il contient des dérivés guanidiniques, notamment la galégine, qui ont été étudiés pour leurs effets hypoglycémiants et ont inspiré le développement de la metformine. Traditionnellement, il a été utilisé en médecine populaire européenne pour la gestion de la glycémie, comme galactagogue pour soutenir la lactation et contre la fièvre. Les usages documentés incluent également des applications astringentes, diaphorétiques, diurétiques, toniques et vermifuges.", "modern_uses": ["Soutien dans le diabète de type 2 (précurseur historique de la metformine)", "Soutien à l'allaitement", "Antihyperglycémiant"], "dosage_adult": "1 à 2 g d'herbe séchée en infusion trois fois par jour", "traditional_uses": ["Gestion traditionnelle du diabète en médecine populaire européenne", "Soutien traditionnel à l'allaitement maternel", "Gestion de la fièvre"]}$fr$::jsonb, true), updated_at = now() WHERE slug = 'goat-rue';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fr${"description": "Lavandula stoechas, communément appelée lavande stéchade, lavande papillon ou ustukhuddus en médecine unani, est un arbuste méditerranéen de la famille des Lamiacées distinct de Lavandula angustifolia. Son huile essentielle se caractérise par une proportion élevée de cétones et d'oxydes monoterpéniques, notamment le camphre, la fenchone et le 1,8-cinéole, avec du bornéol, ce qui lui confère une chimie dépendante du chémotype et nettement plus riche en camphre que la lavande vraie. Les recherches publiées décrivent une activité antimicrobienne in vitro, des effets antispasmodiques sur muscle lisse isolé, une capacité antioxydante liée aux composés phénoliques tels que l'acide rosmarinique et une activité anti-inflammatoire préclinique. Les effets sédatifs et anxiolytiques documentés proviennent surtout d'études in vitro et animales plutôt que de grands essais humains. Les sommités fleuries s'emploient en infusion ou en huile essentielle diluée ; sa teneur élevée en camphre et en fenchone impose un profil de précaution distinct de celui de Lavandula angustifolia.", "dosage_child": "Dose adulte réduite de moitié pour l'infusion sous avis professionnel ; huile essentielle déconseillée chez l'enfant"}$fr$::jsonb, true), updated_at = now() WHERE slug = 'lavender-stoechas';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fr${"name": "Impératoire", "common_names": ["Impératoire", "Ostruthium", "Herbe impériale"], "modern_uses": ["Amer digestif", "Diaphorétique", "Anti-inflammatoire", "Antimicrobien"], "side_effects": ["Brûlures cutanées phototoxiques", "Inconfort gastrique", "Effet fluidifiant sanguin"], "preparation_notes": "Décoction ou infusion de racine ; souvent associée à la gentiane ; phototoxique (éviter l'exposition au soleil après usage)."}$fr$::jsonb, true), updated_at = now() WHERE slug = 'masterwort';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fr${"modern_uses": ["Amer digestif", "Emménagogue", "Antispasmodique", "Antimicrobien"], "traditional_uses": ["Amer digestif et vermifuge en médecine populaire européenne", "Régulation menstruelle et dysménorrhée", "Plante calmante pour l'anxiété et les spasmes", "Base de moxibustion en MTC et médecine japonaise"]}$fr$::jsonb, true), updated_at = now() WHERE slug = 'mugwort-european';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fr${"name": "Osmonde royale"}$fr$::jsonb, true), updated_at = now() WHERE slug = 'osmunda-regalis';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fr${"name": "Benoîte commune", "common_names": ["Herbe de Saint-Benoît", "Benoîte urbaine", "Galiote"], "modern_uses": ["Astringent", "Antimicrobien grâce à l'eugénol", "Anti-inflammatoire", "Amer digestif"], "preparation_notes": "Racine parfumée au clou de girofle ; peut aromatiser les boissons comme le clou de girofle ; associée à l'aigremoine pour la digestion."}$fr$::jsonb, true), updated_at = now() WHERE slug = 'wood-avens';

-- 6. Clean NHP boilerplate & robotic pipeline prose across EN and FR descriptions
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "L'épinette noire (Abies nigra) est un grand conifère pyramidal de 12 à 24 mètres portant de courtes aiguilles vert foncé et des cônes ovales brun rougeâtre. Une décoction concentrée des jeunes rameaux fournit l'essence d'épinette, un liquide épais de saveur acide, amère et astringente, traditionnellement utilisé pour ses propriétés diurétiques et antiscorbutiques ainsi que comme boisson estivale et à bord des navires."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'abies-nigra';
UPDATE public.herbs SET description = $en$Achyranthes aspera is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for gynecological disorders, asthma, ophthalmia, odontalgia. Documented phytochemical constituents include flavonoids, quercetin, kaempferol, and alkaloids. Commercial adult preparations commonly formulate 1000–9000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Achyranthes aspera est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : troubles gynécologiques, asthme, affections oculaires, douleurs dentaires. Les constituants phytochimiques identifiés comprennent notamment flavonoïdes, quercétine, kaempférol et alcaloïdes. Les préparations commerciales pour adultes formulent généralement 1000–9000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'achyranthes-aspera';
UPDATE public.herbs SET description = $en$Actaea heracleifolia, also known as Cimicifuga heracleifolia, is a plant whose dried rhizomes are used in traditional Korean herbal medicine. Its chloroplast genome has been characterized and is 159,578 base pairs in length. The aerial parts contain a new 15,16-seco-cycloartane triterpene, three new cycloartane triterpene glycosides, and five known compounds.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Actaea heracleifolia (syn. Cimicifuga heracleifolia) est une plante dont les rhizomes séchés sont utilisés en médecine traditionnelle coréenne. Ses parties aériennes contiennent des triterpènes de type cycloartane et leurs glycosides, dont un nouveau triterpène 15,16-seco-cycloartane et cinq composés apparentés. Les essais cliniques humains demeurent limités."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'actaea-heracleifolia';
UPDATE public.herbs SET description = $en$Agaricus muscarius is a plant extract used in homeopathic preparations. In animal models, it has been studied for its ability to induce catalepsy. The mechanism appears to involve both dopaminergic and opiate pathways, as catalepsy is reversed by the D1 agonist SKF 38393 and the opiate antagonist naloxone, and potentiated by the D2 agonist bromocriptine and the mixed agonist apomorphine.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Agaricus muscarius est un extrait fongique historiquement employé dans des préparations homéopathiques très diluées (l'amanite tue-mouche fraîche étant toxique). Dans des modèles animaux précliniques, certaines fractions ont été étudiées pour l'induction d'une catalepsie impliquant les voies dopaminergiques et opioïdes ; les essais cliniques humains font défaut."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'agaricus-muscarius';
UPDATE public.herbs SET description = $en$Agraphis nutans is a plant used in homeopathic preparations, including the 5CH potency, in clinical settings for pediatric ear conditions. It has been utilized as part of a homeopathic combination therapy as an adjuvant treatment for otitis media with effusion in children.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Agraphis nutans (jacinthe des bois) est employée dans des préparations homéopathiques très diluées (notamment en dilution 5CH), incluant des associations étudiées comme adjuvant pédiatrique lors d'otites séromuqueuses. Aucun constituant actif standardisé ni essai pharmacologique phytothérapeutique n'est établi."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'agraphis-nutans';
UPDATE public.herbs SET description = $en$Alchemilla xanthochlora, known as yellow-green lady's mantle, is a Rosaceae family herb growing wild in alpine pastures. Its aerial parts contain flavonoids (mean 2.22%), tannins (mean 16.0%), and ellagic acid (mean 0.36%), including quercetin glycosides and ellagitannins. The essential oil is mainly cis-3-hexenol, linalool, oct-1-en-3-ol, and nonanal. It has shown elastase inhibiting activity, while controlled human clinical evidence remains limited.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Alchemilla xanthochlora (alchémille jaune-vert, famille des Rosacées) est une plante des pâturages alpins dont les parties aériennes renferment des flavonoïdes (moyenne 2,22 %), des tanins (16,0 %), de l'acide ellagique et des ellagitanins, ainsi qu'une huile essentielle riche en alcools et aldéhydes foliaires. Elle a montré une activité inhibitrice de l'élastase in vitro."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'alchemilla-xanthochlora';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Aletris farinosa est une petite herbacée nord-américaine à rosette basale de feuilles graminiformes et longue tige florifère. Son rhizome a été employé traditionnellement contre les troubles digestifs, dont l'indigestion, les flatulences et la sensation de plénitude gastrique, ainsi que pour la toux, la bronchite, les irrégularités menstruelles et les règles douloureuses."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'aletris-farinosa';
UPDATE public.herbs SET description = $en$Alyxia sinensis is a plant species whose stems have been chemically investigated, yielding a range of phytochemicals isolated by column chromatography. The isolated constituents include steroids such as beta-sitosterol and stigmasterol, triterpenoids such as lupeol, betulin, ursolic acid, and oleanolic acid, and coumarins such as coumarin and scopletin. Additional compounds identified include physcion, emodin, chrysophanol, and various long-chain alkanes and ketones.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Alyxia sinensis est une espèce végétale dont les tiges ont livré divers composés phytochimiques, dont les stéroïdes bêta-sitostérol et stigmastérol, des triterpénoïdes (lupéol, bétuline, acides ursolique et oléanolique), des coumarines (coumarine, scopolétine) ainsi que de l'émodine et du chrysophanol. L'évaluation clinique humaine fait défaut."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'alyxia-sinensis';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Ampelopsis quinquefolia (vigne vierge) est une liane ligneuse grimpante dont les feuilles à cinq folioles deviennent cramoisies à l'automne et qui produit de petites baies bleu foncé. L'écorce et les jeunes rameaux étaient utilisés traditionnellement, surtout en sirop, comme altératif, tonique, astringent et expectorant contre la scrofule, l'œdème, la bronchite et les affections pulmonaires."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'ampelopsis-quinquefolia';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Anacardium occidentale (noix de cajou) renferme de l'acide gallique, de l'acide anacardique et du cardol. Le suc de l'enveloppe est âcre, caustique et vésicant en usage externe. Traditionnellement, la plante a été mentionnée contre certaines fièvres tropicales, l'épuisement nerveux avec troubles de la mémoire et de l'anxiété, ainsi que diverses affections cutanées."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'anacardium-occidentale';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Anagallis arvensis (mouron rouge) est une herbacée annuelle rampante à tige carrée de 15 à 50 cm, aux feuilles opposées ou verticillées par trois souvent ponctuées de pourpre au revers. La plante était autrefois utilisée traditionnellement contre la manie, les crises convulsives et l'hydropisie, et appliquée en cataplasme sur les ulcères anciens."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'anagallis-arvensis';
UPDATE public.herbs SET description = $en$Ananas comosus var. comosus (cultivated pineapple, family Bromeliaceae) is a tropical fruit crop grown globally for fresh consumption, culinary processing, and disease-resistant commercial cultivars such as 'Pérola' and 'Unemat Rubi'. Beyond whole-fruit nutrition and dietary vitamin C, pineapple stems yield bromelain proteolytic enzymes investigated clinically for localized edema and digestive support, though controlled trials specific to this variety are scarce.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Ananas comosus var. comosus est l'ananas cultivé (famille des Broméliacées), récolté mondialement pour son fruit alimentaire dont de nombreux cultivars sélectionnés pour le rendement et la résistance aux maladies. Au-delà de son apport alimentaire et de la bromélaïne extraite de la tige de l'espèce, les études cliniques propres à ce cultivar sont limitées."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'ananas-comosus-var-comosus';
UPDATE public.herbs SET description = $en$Anemone hepatica is a plant species in the Ranunculaceae family, belonging to the tribe Anemoneae. It shares a similar chloroplast genome gene order with Anemoclema, Anemone, and Hepatica. The herb contains flavonic heterosides as well as anthocyanic and flavonic glycosides.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Anemone hepatica (hépatique noble, famille des Renonculacées) contient des hétérosides flavoniques et anthocyaniques, ainsi que des composés âcres dans la plante fraîche. Son usage médicinal relève surtout des répertoires historiques européens, sans essai clinique humain moderne."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'anemone-hepatica';
UPDATE public.herbs SET description = $en$Angelica decursiva is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for fever, upper respiratory tract infections, bleeding, hypertension. Documented phytochemical constituents include coumarins, scopoletin, bergapten, and imperatorin. Commercial adult preparations commonly formulate 1000–5000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Angelica decursiva est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : fièvre, infections des voies respiratoires supérieures, saignements, hypertension. Les constituants phytochimiques identifiés comprennent notamment coumarines, scopolétine, bergaptène et impératorine. Les préparations commerciales pour adultes formulent généralement 1000–5000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'angelica-decursiva';
UPDATE public.herbs SET description = $en$Apocynum androsaemifolium (spreading dogbane, family Apocynaceae) is a perennial herbaceous plant indigenous to woodlands and thickets across northeastern North America. Like other Apocynum species, its latex and roots contain cardiac-active glycosides and bitter resinous principles, historically noted in North American eclectic texts. Because cardiotonic glycosides carry a narrow safety margin and human clinical trials are lacking, contemporary clinical therapeutic efficacy is unestablished.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Apocynum androsaemifolium (apocyn à feuilles d'androsème, famille des Apocynacées) est une plante herbacée vivace indigène du nord-est de l'Amérique du Nord. Ses racines et son latex renferment des hétérosides cardiotoniques et principes amers mentionnés dans la matière médicale éclectique nord-américaine ; en l'absence d'essais cliniques chez l'humain et en raison d'une marge thérapeutique étroite, l'usage clinique reste non établi."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'apocynum-androsaemifolium';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Apocynum cannabinum (chanvre du Canada) est une plante dressée ramifiée de 60 à 120 cm répandue aux États-Unis, libérant un latex laiteux à la coupe et dotée d'une écorce fibreuse utilisée pour les cordages. Sa racine a été employée traditionnellement contre l'œdème (hydropisie), la dyspepsie et la constipation."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'apocynum-cannabinum';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Arum triphyllum possède un corme aplati gris-brun à l'extérieur et blanc farineux à l'intérieur, surmonté d'un spathe en capuchon. Le corme frais est intensément âcre et brûlant sur la langue et la gorge, propriété qui s'atténue au séchage. Il était traditionnellement utilisé pour les affections de la bouche et de la gorge ainsi que pour certains troubles digestifs."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'arum-triphyllum';
UPDATE public.herbs SET description = $en$Aspergillus niger e volumine cellulae refers to a fungal-derived biological preparation historically listed in specialized homeopathic or biological dilution registries rather than herbal phytotherapy. In biomedical literature, Aspergillus niger is a ubiquitous filamentous fungus studied primarily in industrial enzyme fermentation and microbiological assays rather than as a human therapeutic extract. Controlled clinical data establishing safety or efficacy for oral therapeutic use are lacking.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Aspergillus niger e volumine cellulae désigne une préparation biologique d'origine fongique issue des répertoires homéopathiques plutôt que de la phytothérapie classique. Dans la littérature scientifique, le champignon filamenteux Aspergillus niger est surtout étudié en fermentation enzymatique industrielle et en microbiologie alimentaire ; aucune donnée clinique humaine n'établit d'efficacité thérapeutique."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'aspergillus-niger-e-volumine-cellulae';
UPDATE public.herbs SET description = $en$Bambusa beecheyana is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. Historical practice records its use in multi-herb East Asian decoctions according to classical pattern differentiation. Documented phytochemical constituents include flavonoids, total phenolics, and p-coumaric acid. Commercial adult preparations commonly formulate 1000–4000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Bambusa beecheyana est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Les textes classiques décrivent son emploi au sein de décoctions multi-plantes selon la différenciation des syndromes. Les constituants phytochimiques identifiés comprennent notamment flavonoïdes, composés phénoliques totaux et acide p-coumarique. Les préparations commerciales pour adultes formulent généralement 1000–4000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'bambusa-beecheyana';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Barosma betulina (buchu) est un arbuste sempervirent à feuilles coriaces ponctuées de glandes à huile essentielle dégageant un arôme mentholé. Son huile volatile agit sur les muqueuses des voies urinaires. La plante était traditionnellement utilisée contre les gravelles rénales, le catarrhe vésical chronique, l'irritation de la vessie et de l'urètre, les troubles prostatiques et la faiblesse vésicale."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'barosma-betulina';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Betula lenta (merisier ou bouleau noir) est un grand arbre atteignant 15 à 21 mètres dont l'écorce et les feuilles contiennent des tanins et une huile volatile au parfum de gaulthérie. Elle était traditionnellement utilisée en infusion chaude comme stimulant doux, diaphorétique et astringent, ainsi que contre la diarrhée, la dysenterie et pour restaurer le tonus intestinal après une dysenterie."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'betula-lenta';
UPDATE public.herbs SET description = $en$Brassica oleracea var. gemmifera, commonly known as Brussels sprouts, is a plant species that has been studied for its volatile responses to herbivory. When damaged by Pieris brassicae larvae or treated with larval regurgitant, the plant releases greenleaf volatiles and several terpenoids that attract the parasitoid Cotesia glomerata. It can also be susceptible to Sclerotinia sclerotiorum infection.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Brassica oleracea var. gemmifera (chou de Bruxelles) est une crucifère alimentaire étudiée pour l'émission de composés volatils et terpénoïdes en réponse aux herbivores ainsi que pour sa richesse nutritionnelle en glucosinolates. Son intérêt relève essentiellement de l'alimentation plutôt que d'essais cliniques pharmacologiques."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'brassica-oleracea-var-gemmifera';
UPDATE public.herbs SET description = $en$Brassica oleracea var. viridis (collard greens and tree kale, family Brassicaceae) is a leafy cultivar group widely consumed as a nutrient-dense cruciferous vegetable. Like related Brassica oleracea crops, its leaves contain glucosinolates, phenolic antioxidants, carotenoids, and minerals, alongside agronomic traits enabling metal tolerance in Brassicaceae soils. Dedicated clinical trials isolating this specific botanical variety for therapeutic outcomes remain limited.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Brassica oleracea var. viridis (chou cavalier, famille des Brassicacées) est une variété potagère cultivée pour ses feuilles riches en glucosinolates, composés phénoliques, caroténoïdes et minéraux. Comme d'autres crucifères alimentaires, son intérêt est avant tout nutritionnel, et peu d'essais cliniques isolent spécifiquement cette variété botanique à des fins thérapeutiques."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'brassica-oleracea-var-viridis';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Le navet (Brassica rapa) est une plante potagère de la famille des Brassicacées également utilisée comme fourrage hivernal. Le bouillon de racine servait traditionnellement à favoriser la diurèse, tandis que la racine avait un léger effet laxatif. La pulpe écrasée avec du pain et du lait s'appliquait en cataplasme sur les abcès et plaies torpides."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'brassica-rapa';
UPDATE public.herbs SET description = $en$Bromus ramosus (hairy brome) is a perennial woodland grass in the family Poaceae distributed across shaded European, Asian, and North African habitats. Botanical literature focuses primarily on its ecology and mutualistic symbiosis with the seed-transmitted fungal endophyte Epichloe bromicola rather than human pharmacology. Phytochemical characterization and controlled clinical studies evaluating medicinal efficacy in humans are lacking.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Bromus ramosus (brome rameux) est une graminée vivace forestière de la famille des Poacées présente en Europe, en Asie et en Afrique du Nord. La littérature scientifique porte principalement sur son écologie et sa symbiose avec le champignon endophyte Epichloe bromicola ; aucune étude clinique n'établit d'efficacité thérapeutique chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'bromus-ramosus';
UPDATE public.herbs SET description = $en$Candida parapsilosis is an opportunistic yeast in the psilosis complex, alongside C. orthopsilosis and C. metapsilosis. It is a leading cause of invasive candidiasis, especially in neonates and immunocompromised patients, and ranks second among candidemia species in parts of Europe, Latin America, South Africa, and Asia. Its pathogenesis involves secreted hydrolytic enzymes, adhesion to prosthetics, and biofilm formation, and it can produce eicosanoids.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Candida parapsilosis est une levure opportuniste du complexe psilosis étudiée en mycologie médicale pour sa capacité à former des biofilms et produire des enzymes hydrolytiques et des eicosanoïdes. Il ne s'agit pas d'une plante médicinale mais d'un micro-organisme d'intérêt infectieux et biologique, sans démonstration d'efficacité thérapeutique."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'candida-parapsilosis';
UPDATE public.herbs SET description = $en$Capsicum annuum var. annuum is a pepper variety that includes the Peter pepper and cultivars such as Charleston Belle, Carolina Wonder, and Carolina Cayenne. Its fruits contain capsaicinoids, including capsaicin, dihydrocapsaicin, nordihydrocapsaicin, homocapsaicin, and homodihydrocapsaicin, which increase in concentration as the fruit ripens.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Capsicum annuum var. annuum regroupe diverses variétés cultivées de piments et poivrons dont les fruits synthétisent des capsaïcinoïdes (capsaïcine, dihydrocapsaïcine, nordihydrocapsaïcine) dont la teneur croît au cours de la maturation. La capsaïcine topique est étudiée dans les douleurs neuropathiques ou musculaires."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'capsicum-annuum-var-annuum';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Le chardon bénit (Carduus benedictus) est une herbacée annuelle ramifiée à tiges rougeâtres, feuilles découpées et capitules jaunes épineux. L'herbe était employée traditionnellement comme amer tonique contre le manque d'appétit et la dyspepsie, et en infusion chaude comme diaphorétique et emménagogue au début des fièvres ou en cas d'aménorrhée liée au froid."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'carduus-benedictus';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Le séné (Cassia acutifolia) est employé en médecine depuis le IXe siècle dans la tradition arabe. Son action s'exerce principalement sur le côlon par stimulation locale du péristaltisme, ce qui le rendait utile dans la constipation habituelle, souvent associé à des plantes aromatiques pour limiter les coliques. Des pigments actifs peuvent colorer l'urine et passer dans le lait maternel."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'cassia-acutifolia';
UPDATE public.herbs SET description = $en$Chamaesyce hirta is a spontaneous euphorbiaceous plant found in rubber tree cultivations and used as a medicinal plant in India. It has demonstrated antibacterial activity against specific enteropathogens. Published biomedical research includes antibacterial evaluation against selected enteropathogens, though controlled human clinical trials remain scarce.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Chamaesyce hirta (syn. Euphorbia hirta) est une herbacée spontanée des régions tropicales employée en médecine traditionnelle indienne, notamment contre les affections digestives et respiratoires, et dont des extraits ont montré une activité antibactérienne in vitro sur plusieurs entéropathogènes."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'chamaesyce-hirta';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "La giroflée des murailles (Cheiranthus cheiri) est une ancienne plante ornementale d'Europe appréciée pour son parfum vif. Macérées dans l'huile, ses fleurs servaient traditionnellement contre les douleurs rhumatismales ou névralgiques, tandis que l'infusion était employée pour les céphalées asthéniques, les troubles nerveux et comme cordial."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'cheiranthus-cheiri';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Chelone glabra (galane glabre) est une herbacée vivace de 60 à 90 cm aux feuilles oblongues dentées et aux fleurs tubulaires groupées rappelant une tête de tortue. La plante était utilisée traditionnellement comme tonique amer, cholagogue, cathartique doux et vermifuge, notamment en cas d'ictère, d'atteinte hépatique, de vers intestinaux et en convalescence après les fièvres palustres."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'chelone-glabra';
UPDATE public.herbs SET description = $en$Chrysanthellum americanum is a medicinal plant in the Compositae family, used in West African traditional medicine and known for its strong antioxidant potential. It contains flavonoids, saponins, phenolic compounds, and proanthocyanidin oligomers, along with the isolated compound chrysanamerine and polyacetylene. In vitro studies indicate that certain compounds inhibit pteridine reductase-1, a target in Leishmania parasites.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Chrysanthellum americanum (famille des Astéracées) est une plante médicinale utilisée en médecine traditionnelle ouest-africaine et connue pour ses polyphénols antioxydants : flavonoïdes, saponines, proanthocyanidines, chrysanamérine et polyacétylènes. Certains extraits inhibent in vitro la ptéridine réductase-1 chez Leishmania, sans essais cliniques humains approfondis."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'chrysanthellum-americanum';
UPDATE public.herbs SET description = $en$Chrysanthemum x morifolium is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. Historical practice records its use in multi-herb East Asian decoctions according to classical pattern differentiation. Documented phytochemical constituents include sesquiterpene lactones, beta-carotene, and parthenolide. Commercial adult preparations commonly formulate 1000–4000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Chrysanthemum x morifolium est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Les textes classiques décrivent son emploi au sein de décoctions multi-plantes selon la différenciation des syndromes. Les constituants phytochimiques identifiés comprennent notamment lactones sesquiterpéniques, bêta-carotène et parthénolide. Les préparations commerciales pour adultes formulent généralement 1000–4000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'chrysanthemum-x-morifolium';
UPDATE public.herbs SET description = $en$Cistanche salsa is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for kidney deficiency, neurasthenia, sexual dysfunction diseases, benign prostatic hyperplasia. Documented phytochemical constituents include beta-sitosterol, iridoids, tubuloside b, and acteoside. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Cistanche salsa est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : déficience rénale selon la MTC, neurasthénie, dysfonctionnements sexuels, hyperplasie bénigne de la prostate. Les constituants phytochimiques identifiés comprennent notamment bêta-sitostérol, iridoïdes, tubuloside B et actéoside. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'cistanche-salsa';
UPDATE public.herbs SET description = $en$Citrullus lanatus var. lanatus is the cultivated watermelon (family Cucurbitaceae), grown globally for its hydrating, sweet fruit flesh and edible seeds. Watermelon juice and pulp provide dietary phytochemicals including carotenoids such as lycopene, phenolic acids, flavonoids, and the non-essential amino acid L-citrulline, which has been investigated in cardiovascular and exercise-physiology studies. Therapeutic claims beyond general dietary nutrition depend on concentrated extracts rather than whole fruit.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Citrullus lanatus var. lanatus est la variété cultivée de la pastèque (famille des Cucurbitacées), consommée mondialement pour sa pulpe riche en eau et ses graines. Elle apporte des caroténoïdes (notamment du lycopène), des acides phénoliques, des flavonoïdes et de la L-citrulline étudiée en physiologie vasculaire ; l'intérêt principal demeure nutritionnel."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'citrullus-lanatus-var-lanatus';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Le citronnier (Citrus limonum) fleurit toute l'année et fournit à la fois le jus et l'écorce aromatique. Le jus servait traditionnellement contre le scorbut, pour soutenir la digestion biliaire, apaiser les palpitations nerveuses et atténuer les douleurs ulcéreuses buccales, tandis que le zeste fournissait un amer aromatique. En Italie, la décoction de citron entier servait contre les fièvres intermittentes."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'citrus-limonum';
UPDATE public.herbs SET description = $en$Clematis erecta (upright virgin's bower, family Ranunculaceae) is a perennial European herb traditionally recorded in older homeopathic and historical European materia medica. Fresh aerial parts of Clematis species contain the irritant lactone protoanemonin, which dimerizes to anemonin upon drying and gives fresh material vesicant properties. Modern human clinical trial data verifying safety or therapeutic efficacy are lacking.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Clematis erecta (clématite droite, famille des Renonculacées) est une herbacée vivace européenne mentionnée dans d'anciens répertoires homéopathiques et matières médicales traditionnelles. Les parties fraîches des clématites contiennent de la protoanémonine irritante ; les données cliniques modernes chez l'humain font défaut."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'clematis-erecta';
UPDATE public.herbs SET description = $en$Clematis montana is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for medicinal plant use in southwest china. Documented phytochemical constituents include a mannose-binding lectin. Commercial adult preparations commonly formulate 1000–8000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Clematis montana est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : usages médicinaux traditionnels du sud-ouest de la Chine. Les constituants phytochimiques identifiés comprennent notamment une lectine liant le mannose. Les préparations commerciales pour adultes formulent généralement 1000–8000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'clematis-montana';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Codonopsis tangshen est une plante médicinale répertoriée dans les ouvrages de matière médicale du début du XXe siècle et utilisée traditionnellement en médecine asiatique. Elle était employée pour soulager la toux, soutenir les fonctions digestives et remédier aux états de faiblesse générale."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'codonopsis-tangshen';
UPDATE public.herbs SET description = $en$Coenzyme Q10, also called ubiquinone or ubiquinol, is a compound that occurs naturally in the body and is involved in cellular energy production. It exists in two forms: an oxidized form called ubiquinone and a reduced form called ubiquinol. Coenzyme Q10 has been used traditionally for heart health, fatigue, and aging. Clinical trials most commonly examine supplementation in cardiovascular support and statin-associated myalgia, though results vary across formulations.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "La coenzyme Q10 (CoQ10), également appelée ubiquinone sous sa forme oxydée et ubiquinol sous sa forme réduite, est une molécule endogène essentielle à la chaîne respiratoire mitochondriale et à la production d'ATP cellulaire. En supplémentation adulte, elle est étudiée pour le soutien cardiaque, la fatigue mitochondriale et l'état oxydatif."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'coq10-antioxidant';
UPDATE public.herbs SET description = $en$Corydalis turtschaninovii is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for memory enhancement, analgesic effects, chronic pain, tumor therapy. Documented phytochemical constituents include alkaloids, berberine, tetrahydropalmatine, and dehydrocorydaline. Commercial adult preparations commonly formulate 1000–4000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Corydalis turtschaninovii est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : soutien de la mémoire, douleurs et recherche d'effets antalgiques, douleurs chroniques, recherche antitumorale. Les constituants phytochimiques identifiés comprennent notamment alcaloïdes, berbérine, tétrahydropalmatine et déhydrocorydaline. Les préparations commerciales pour adultes formulent généralement 1000–4000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'corydalis-turtschaninovii';
UPDATE public.herbs SET description = $en$Cucumis melo subsp. melo var. cantalupo is the cantaloupe melon (family Cucurbitaceae), a widely cultivated sweet fruit rich in beta-carotene, vitamin C, phenolic acids, and flavonoids. Phytochemical research across Cucumis melo cultivars also identifies cucurbitane-type triterpenoids and stress-response enzymes, while fruit and seed extracts have been noted traditionally for mild soothing or skin-care applications. Controlled human therapeutic trials remain scarce.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Cucumis melo subsp. melo var. cantalupo est le melon cantaloup (famille des Cucurbitacées), fruit alimentaire riche en bêta-carotène, vitamine C, acides phénoliques et flavonoïdes. La recherche phytochimique sur les cultivars de Cucumis melo identifie aussi des triterpénoïdes cucurbitanes, sans essai clinique thérapeutique concluant chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'cucumis-melo-subsp-melo-var-cantalupo';
UPDATE public.herbs SET description = $en$Cupressus lawsoniana (syn. Chamaecyparis lawsoniana, Lawson cypress or Port Orford cedar, family Cupressaceae) is a large coniferous tree native to southwestern Oregon and northwestern California. Its wood and foliage yield aromatic essential oils containing monoterpenes and sesquiterpenes, and dilutions have occasionally appeared in historical homeopathic monographs. Controlled human clinical evidence for medicinal use is lacking.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Cupressus lawsoniana (cyprès de Lawson, famille des Cupressacées) est un grand conifère originaire du nord-ouest de l'Amérique du Nord. Son feuillage et son bois renferment des huiles essentielles riches en terpènes, et certaines dilutions ont figuré dans d'anciens répertoires homéopathiques, sans essai clinique démontrant d'efficacité chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'cupressus-lawsoniana';
UPDATE public.herbs SET description = $en$Curcuma kwangsiensis is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for pain, depression, jaundice, red urine. Documented phytochemical constituents include terpenoids, sesquiterpenes, polysaccharides, and curcumin. Commercial adult preparations commonly formulate 1000–3000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Curcuma kwangsiensis est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : douleurs, troubles de l'humeur, ictère (jaunisse), urines foncées. Les constituants phytochimiques identifiés comprennent notamment terpénoïdes, sesquiterpènes, polysaccharides et curcumine. Les préparations commerciales pour adultes formulent généralement 1000–3000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'curcuma-kwangsiensis';
UPDATE public.herbs SET description = $en$Cynanchum glaucescens (Bai Qian, family Apocynaceae) is a medicinal herb whose roots and rhizomes are used in Traditional Chinese Medicine decoctions for respiratory and inflammatory complaints. In classical East Asian practice, it is traditionally valued for antitussive, expectorant, and phlegm-clearing actions in bronchitis and asthmatic coughs. Modern clinical trial evidence remains preliminary and derives mostly from multi-herb formulations.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Cynanchum glaucescens (Bai Qian, famille des Apocynacées) est une plante médicinale dont les racines sont employées en médecine traditionnelle chinoise contre les troubles respiratoires et la toux avec mucosités. La tradition lui attribue des effets antitussifs et expectorants, bien que les essais cliniques contrôlés sur la plante isolée demeurent rares."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'cynanchum-glaucescens';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Cypripedium pubescens (sabot de Vénus jaune) est une orchidée nord-américaine documentée dans la pratique médicinale du début du XXe siècle. Elle était traditionnellement utilisée comme nervin doux contre la nervosité, l'agitation, l'insomnie, l'irritabilité, les céphalées nerveuses et les névralgies, notamment en lien avec la sphère génito-urinaire."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'cypripedium-pubescens';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Daphne mezereum (bois gentil) est un arbuste dont l'écorce, les baies et les feuilles sont fortement actives et vésicantes. L'écorce fraîche provoque inflammation et cloques cutanées et servait autrefois d'agent révulsif en Europe du Sud; la pommade s'appliquait sur les ulcères torpides. En usage interne, la plante n'était employée qu'à très faible dose, notamment dans les décoctions de salsepareille."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'daphne-mezereum';
UPDATE public.herbs SET description = $en$Descurainia sophia is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for cough, phlegm, asthma, inflammatory airway disease. Documented phytochemical constituents include flavonoids, phenolic acids, phytosterols, and glucosinolates. Commercial adult preparations commonly formulate 1000–3000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Descurainia sophia est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : toux, mucosités respiratoires, asthme, inflammation des voies respiratoires. Les constituants phytochimiques identifiés comprennent notamment flavonoïdes, acides phénoliques, phytostérols et glucosinolates. Les préparations commerciales pour adultes formulent généralement 1000–3000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'descurainia-sophia';
UPDATE public.herbs SET description = $en$Dictamnus dasycarpus is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for skin disorders, pruritus, eczema, rubella. Documented phytochemical constituents include flavonoids, and alkaloids. Commercial adult preparations commonly formulate 1000–3000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Dictamnus dasycarpus est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : affections cutanées, prurit, eczéma, éruptions cutanées. Les constituants phytochimiques identifiés comprennent notamment flavonoïdes et alcaloïdes. Les préparations commerciales pour adultes formulent généralement 1000–3000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'dictamnus-dasycarpus';
UPDATE public.herbs SET description = $en$Dioscorea futschauensis is a plant in the Dioscoreaceae family whose rhizomes contain saponins and glycosides, including pregnane glycosides, spirostanol saponins such as dioscin, furostanol glycosides, and the triterpene glycoside DRG. In vitro studies have shown that DRG induces apoptosis in human colon carcinoma cells and that prosapogenin B of dioscin induces apoptosis in K562 cells. The species is also known by names such as Fuzhou Dioscorea and Dioscorea septemloba.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Dioscorea futschauensis (famille des Dioscoréacées) est une espèce dont les rhizomes contiennent des saponines stéroïdiennes et glycosides prégnanes, notamment la dioscine et le glycoside DRG. Des travaux in vitro rapportent une induction d'apoptose sur certaines lignées cellulaires tumorales sans validation clinique chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'dioscorea-futschauensis';
UPDATE public.herbs SET description = $en$Dolichos pruriens (historical botanical name often allied with Mucuna pruriens, family Fabaceae) is a tropical leguminous climber whose seed pods bear irritating trichomes. In homeopathic and experimental literature, dilutions and extracts have been evaluated in rodent models for effects on pruritus and skin lesions, while related Mucuna species are studied for L-DOPA content. Clinical human efficacy remains unestablished.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Dolichos pruriens (dénomination historique souvent rattachée à Mucuna pruriens, famille des Fabacées) est une légumineuse grimpante dont les gousses portent des poils urticants. En littérature homéopathique et préclinique, ses extraits ont été étudiés dans des modèles animaux contre le prurit et certaines lésions cutanées, sans preuve clinique humaine établie."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'dolichos-pruriens';
UPDATE public.herbs SET description = $en$Dolomiaea souliei is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for gastrointestinal diseases. Documented phytochemical constituents include sesquiterpene lactones. Commercial adult preparations commonly formulate 1000–2000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Dolomiaea souliei est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : troubles gastro-intestinaux. Les constituants phytochimiques identifiés comprennent notamment lactones sesquiterpéniques. Les préparations commerciales pour adultes formulent généralement 1000–2000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'dolomiaea-souliei';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Duboisia myoporoides est un grand arbuste originaire d'Australie et de Nouvelle-Calédonie aux feuilles alternes lisses et petites fleurs blanches en panicules. La plante et son alcaloïde duboisine étaient utilisés traditionnellement dans des indications analogues à celles de la belladone et de la jusquiame pour leurs effets anticholinergiques marqués."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'duboisia-myoporoides';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "La sauge d'Afrique de l'Est (Plectranthus barbatus), également connue sous les noms de Coleus forskohlii ou boldo du Brésil, est une herbe médicinale vivace tropicale de la famille des Lamiacées. Elle est largement cultivée en Inde et utilisée dans la médecine hindoue, ayurvédique et traditionnelle au Brésil, en Afrique tropicale et en Chine. Les utilisations ethnobotaniques majeures comprennent le traitement des troubles intestinaux, de la fatigue hépatique, des troubles respiratoires, des maladies cardiaques et de certains troubles du système nerveux. Elle est également utilisée pour la bronchite, l'asthme, le rhume des foins, l'angine et les troubles abdominaux. La plante contient des huiles essentielles, des diterpénoïdes abiétanes et des diterpénoïdes de type 8,13-époxy-labd-14-én-11-one. Un constituant actif principal est la forskoline, un diterpénoïde de type labdane trouvé exclusivement dans le tissu de liège des racines. Elle aide temporairement à favoriser la vigilance et l'éveil, et à améliorer les performances cognitives."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'east-african-sage';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Epimedium sagittatum est une plante médicinale traditionnelle principalement utilisée en Asie pour traiter la dysfonction érectile. Arrêter l'utilisation en cas de vertiges, vomissements, sécheresse de la bouche, soif, saignements de nez, insomnie, anxiété, maux de tête, ou symptômes de faible taux d'œstrogènes ou de troubles hépatiques. Un effet diurétique peut survenir. Les femmes adultes doivent consulter un professionnel de la santé en cas de pousse anormale des cheveux. Les femmes ménopausées et post-ménopausées doivent consulter un professionnel de la santé pour une utilisation au-delà de 6 semaines. Une hypersensibilité ou allergie est possible; dans ce cas, cesser l'utilisation. Certaines personnes peuvent éprouver de l'insomnie, de l'anxiété ou des maux de tête; dans ce cas, cesser l'utilisation. Consulter un professionnel de la santé si les symptômes persistent ou s'aggravent, ou si de nouveaux symptômes apparaissent."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'epimedium-sagittatum';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Eupatorium purpureum (eupatoire pourpre) est une grande herbacée vivace atteignant 1,5 à 1,8 mètre, à feuilles verticillées et corymbes de fleurs pourpres ou rosées. Sa racine était traditionnellement utilisée comme diurétique, stimulant, tonique et antilithiasique exerçant une action élective sur les reins, ainsi que comme diaphorétique dans les fièvres faibles."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'eupatorium-purpureum';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Fabiana imbricata (pichi) est un arbuste atteignant 4,5 à 6 mètres aux petites feuilles bleu-vert imbriquées et fleurs tubulaires blanches ou violacées. La plante était traditionnellement employée comme diurétique, tonique digestif et stimulant hépatique dans la dyspepsie et la jaunisse."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'fabiana-imbricata';
UPDATE public.herbs SET description = $en$Foeniculum vulgare subsp. vulgare var. vulgare (bitter or wild fennel, family Apiaceae) is an aromatic perennial herb native to the Mediterranean basin. Its fruits contain an essential oil rich in trans-anethole, fenchone, and monoterpenes such as limonene and alpha-pinene. Traditional European herbal monographs recognize fennel fruit preparations as mild carminatives for spasmodic bloating and flatulence and as expectorants for cough associated with colds.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Foeniculum vulgare subsp. vulgare var. vulgare (fenouil amer, famille des Apiacées) est une plante vivace aromatique méditerranéenne dont les fruits renferment une huile essentielle riche en trans-anéthole, fenchone et monoterpènes (limonène, alpha-pinène). La tradition phytothérapeutique européenne reconnaît son emploi contre les ballonnements spasmodiques, les flatulences et comme expectorant lors de toux bénigne."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'foeniculum-vulgare-subsp-vulgare-var-vulgare';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Franciscea uniflora (manacá) est un arbuste très ramifié portant des fleurs solitaires blanches, bleues ou violettes. La racine et la tige étaient traditionnellement employées contre les rhumatismes et certaines affections chroniques, avec une action attribuée aux glandes, au système nerveux et à la diurèse accompagnée de sudation abondante."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'franciscea-uniflora';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Fraxinus americana (frêne blanc d'Amérique) est un grand arbre forestier de 15 à 24 mètres à écorce grise sillonnée et feuilles pennées. L'écorce était utilisée traditionnellement comme tonique, astringent et léger purgatif contre la constipation et l'hydropisie, et macérée dans le vin contre la splénomégalie post-palustre."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'fraxinus-americana';
UPDATE public.herbs SET description = $en$Fraxinus chinensis is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for bacterial disorders, enteritis, leukorrhea, chronic bronchitis. Documented phytochemical constituents include flavonoids, terpenoids, coumarins, and lignans. Commercial adult preparations commonly formulate 1000–4000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Fraxinus chinensis est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : affections bactériennes, entérite, leucorrhées, bronchite chronique. Les constituants phytochimiques identifiés comprennent notamment flavonoïdes, terpénoïdes, coumarines et lignanes. Les préparations commerciales pour adultes formulent généralement 1000–4000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'fraxinus-chinensis';
UPDATE public.herbs SET description = $en$Gentiana manshurica is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for ischemic-inflammatory disorders, swelling, pain, heat and dampness. Documented phytochemical constituents include flavonoids, kaempferol, alkaloids, and terpenoids. Commercial adult preparations commonly formulate 1000–6000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Gentiana manshurica est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : troubles inflammatoires et ischémiques, œdèmes et gonflements, douleurs, chaleur-humidité selon la tradition chinoise. Les constituants phytochimiques identifiés comprennent notamment flavonoïdes, kaempférol, alcaloïdes et terpénoïdes. Les préparations commerciales pour adultes formulent généralement 1000–6000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'gentiana-manshurica';
UPDATE public.herbs SET description = $en$Heliamphora nutans, also called Sun Pitcher or Marsh Pitcher Plant, is a carnivorous plant endemic to the tepuis of Venezuela. It is traditionally recorded for fever and ritual use by indigenous communities. The plant contains tannins and flavonoids, and proteases have been identified in its tissues. Published biomedical research on human clinical efficacy or safe dosing is lacking.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Heliamphora nutans (plante carnivore des tepuys du Venezuela) est documentée dans l'ethnobotanique locale pour la fièvre et certains usages rituels. Ses tissus contiennent des tanins, des flavonoïdes et des protéases digestives, sans études cliniques humaines publiées."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'heliamphora-nutans';
UPDATE public.herbs SET description = $en$Hepatica triloba (syn. Anemone hepatica, common liverleaf, family Ranunculaceae) is a woodland perennial native to Europe whose three-lobed leaves historically inspired its use under the medieval doctrine of signatures. Phytochemical analyses report saponins and flavonic glycosides alongside protoanemonin-forming constituents in fresh tissue. Clinical trial evidence is lacking, and contemporary use is largely historical or botanical.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Hepatica triloba (hépatique à trois lobes, syn. Anemone hepatica, famille des Renonculacées) est une vivace forestière européenne riche en saponines et glycosides flavoniques. Employée autrefois selon la théorie des signatures pour les troubles hépatiques, elle ne bénéficie pas d'essais cliniques modernes démontrant une efficacité thérapeutique."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'hepatica-triloba';
UPDATE public.herbs SET description = $en$Heptapleurum arboricola (syn. Schefflera arboricola, dwarf umbrella tree, family Araliaceae) is a tropical evergreen shrub native to Taiwan and southern China. While widely grown ornamentally, roots and stems of related Heptapleurum species appear occasionally in traditional East Asian folk medicine for musculoskeletal pain and circulation. Formal clinical studies and detailed human safety data for H. arboricola are absent.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Heptapleurum arboricola (arbre-parapluie nain, syn. Schefflera arboricola, famille des Araliacées) est un arbuste sempervirent originaire de Taïwan et du sud de la Chine. Bien que principalement ornemental, certaines espèces voisines figurent en médecine populaire est-asiatique contre les douleurs circulatoires ou musculaires, sans données cliniques chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'heptapleurum-arboricola';
UPDATE public.herbs SET description = $en$Hottonia palustris is a distylous, clonal aquatic plant in the Primulaceae family. Its aerial parts contain flavonoids and polyphenolic compounds, including polymethoxyflavones, hottonioside A, and the chalcone dibenzoylmethane. In vitro studies show that dibenzoylmethane blocks large-conductance calcium-activated potassium channels, while certain flavonoids interact with phospholipid bilayers.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Hottonia palustris (hottonie des marais, famille des Primulacées) est une plante aquatique clonale dont les parties aériennes renferment des flavonoïdes polyméthoxylés, l'hottonioside A et le dibenzoylméthane. In vitro, certains constituants modulent des canaux potassiques calciques ; aucune preuve clinique humaine n'existe."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'hottonia-palustris';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Ignatia amara (fève de Saint-Ignace) était décrite dans les pharmacopées historiques comme un remède spinal augmentant la sensibilité nerveuse. Elle était traditionnellement utilisée dans les états d'hypersensibilité émotionnelle avec soupirs, pleurs et sensation de boule dans la gorge, les céphalées nerveuses, les troubles menstruels et la dyspepsie nerveuse."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'ignatia-amara';
UPDATE public.herbs SET description = $en$Iris domestica is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for respiratory diseases, inflammation, throat disorders. Documented phytochemical constituents include isoflavones, polyphenols, and stilbenes. Commercial adult preparations commonly formulate 1000–1500 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Iris domestica est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : affections respiratoires, états inflammatoires, affections de la gorge. Les constituants phytochimiques identifiés comprennent notamment isoflavones, polyphénols et stilbènes. Les préparations commerciales pour adultes formulent généralement 1000–1500 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'iris-domestica';
UPDATE public.herbs SET description = $en$Iris tenax, known as the Oregon iris, is a perennial plant native to the grassland prairies of western Oregon and Washington. These prairie ecosystems are among the most endangered in the United States. Phytochemical profiling of Iris tenax extracts has identified flavonoids and iridals as constituents.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Iris tenax (iris de l'Oregon) est une vivace originaire des prairies menacées de l'Oregon et de l'État de Washington. Le profilage phytochimique de ses extraits a identifié des flavonoïdes et des iridals, sans évaluation clinique thérapeutique chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'iris-tenax';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Zingiber mioga (Thunb.) Roscoe, de la famille des Zingiberaceae, est une herbacée vivace originaire du Japon et de l'Asie de l'Est, cultivée principalement pour ses boutons floraux immatures et ses jeunes pousses, consommés comme légume de saison. Contrairement au gingembre commun, le rhizome n'est pas l'organe comestible principal. La caractérisation phytochimique de l'espèce a identifié des constituants diarylheptanoïdes et des composés phénoliques apparentés au gingembre, notamment le myogadial (composés de type galanal), le myogaenol et des membres de la série des gingérols/shogaols, ainsi que des polysaccharides hydrosolubles isolés à partir de la biomasse foliaire. L'analyse in vitro de polysaccharides foliaires extraits par micro-ondes ultrasoniques a démontré une activité antioxydante et un potentiel anticoagulant, bien que ces résultats n'aient pas été traduits en essais cliniques humains. Les ressources génomiques comprennent un génome chloroplastique caractérisé, soutenant la recherche taxonomique et l'authentification. La portée clinique demeure étroite: aucun essai contrôlé randomisé évaluant les effets thérapeutiques chez l'humain n'a été identifié dans la littérature publiée ; les preuves se limitent à la caractérisation des constituants et à la pharmacologie in vitro."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'japanese-myoga-ginger';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Salvia dominica (sauge de Jordanie) est un arbuste vivace aromatique de la famille des Lamiacées, originaire de Jordanie et du Levant, où elle pousse sur les collines rocheuses et dans la végétation de phrygana méditerranéenne. Sur le plan taxonomique, elle appartient à un grand genre dont les espèces se caractérisent par des glandes à huile essentielle, la production de résines diterpéniques et l'accumulation d'acides phénoliques. L'étude phytochimique des populations jordaniennes a caractérisé les profils d'émission de composés organiques volatils des organes reproducteurs et végétatifs, avec une variation observée entre les populations, indiquant une composition chimiotype-dépendante de la fraction d'huile essentielle. Les classes de constituants documentées comprennent des huiles volatiles hydrodistillées riches en monoterpènes et sesquiterpènes hydrocarbonés, des acides phénoliques tels que l'acide rosmarinique et des dérivés d'acide salvianolique, des triterpènes pentacycliques dont l'acide ursolique, et des diterpénoïdes de type abiétane caractéristiques des espèces de Salvia. Des travaux in vitro ont examiné l'activité antiproliférative d'extraits de Salvia dominica et d'espèces apparentées contre des lignées de cellules tumorales humaines, établissant un signal préliminaire de cytotoxicité sans données translationnelles humaines. D'autres essais in vitro sur diverses espèces de Salvia suggèrent une activité antimicrobienne et antioxydante attribuable aux fractions phénoliques et terpénoïdes. Sur le plan clinique, aucun essai contrôlé randomisé chez l'humain n'a été identifié dans la littérature publiée ; par conséquent, les allégations thérapeutiques restent limitées à la documentation ethnobotanique et à la pharmacologie au stade de laboratoire."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'jordan-sage';
UPDATE public.herbs SET description = $en$Lachnanthes tinctoria (Carolina redroot, family Haemodoraceae) is a wetland perennial native to eastern North America known for its striking red-pigmented rhizomes. Its roots contain arylphenalenone and photodynamic pigments characteristic of the family. Historically referenced in nineteenth-century American eclectic and homeopathic texts for torticollis and nervous headaches, modern human clinical trials are absent.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Lachnanthes tinctoria (racine rouge de Caroline, famille des Hæmodoracées) est une vivace des zones humides d'Amérique du Nord caractérisée par ses rhizomes contenant des pigments arylphénalénones photodynamiques. Citée autrefois dans la matière médicale homéopathique américaine contre le torticolis et certaines céphalées, elle manque d'études cliniques modernes."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'lachnanthes-tinctoria';
UPDATE public.herbs SET description = $en$Lactuca quercina (family Asteraceae) is a wild lettuce species native to central and eastern Europe. Like other wild Lactuca species, it produces bitter milky latex containing sesquiterpene lactones, though far less studied chemically than Lactuca virosa or Lactuca serriola. Dedicated pharmacological and human clinical trials evaluating medicinal applications of L. quercina are absent.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Lactuca quercina (laitue à feuilles de chêne, famille des Astéracées) est une espèce sauvage européenne produisant un latex amer contenant probablement des lactones sesquiterpéniques, bien moins étudiée que Lactuca virosa. Aucun essai clinique ou étude pharmacologique approfondie ne valide d'usage thérapeutique spécifique chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'lactuca-quercina';
UPDATE public.herbs SET description = $en$Lasiosphaera fenzlii is a puffball mushroom whose extracts and compounds have been studied in laboratory research. Identified constituents include the lipodepsipeptide white-line-inducing principle and several ergostane-type sterols. In vitro studies report anticancer activity and telomerase inhibition, and the mushroom has been used clinically for hemostasis during prostatectomy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Lasiosphaera fenzlii est une vesse-de-loup dont les extraits renferment des stérols de type ergostane et un lipodepsipeptide étudiés in vitro pour une inhibition de la télomérase. Le champignon séché a été utilisé en milieu hospitalier en Chine comme hémostatique local, mais les essais contrôlés demeurent limités."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'lasiosphaera-fenzlii';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Leptandra virginica (racine de Culver) est une plante médicinale nord-américaine documentée au début du XXe siècle. Elle était traditionnellement utilisée pour stimuler le flux biliaire et soutenir la fonction hépatique, dans les fièvres rémittentes, l'ictère et la constipation atonique accompagnée de céphalées sourdes ou de vertiges."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'leptandra-virginica';
UPDATE public.herbs SET description = $en$Ligusticum sinense var. sinense is a Chinese medicinal herb, with related cultivars traditionally used as a medicinal tea for headache relief in southern China. Its primary active compound, tetramethylpyrazine, has been studied for mitigating oxidative damage in spinal cord injury. Extracts have shown inhibitory activity against Malassezia furfur and its biofilms, and have alleviated migraine-like responses in rats.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Ligusticum sinense var. sinense est une plante médicinale chinoise dont les cultivars voisins sont employés traditionnellement en tisane contre les céphalées dans le sud de la Chine. La tétraméthylpyrazine, son composé majeur, est étudiée en préclinique pour la protection neuronale et l'activité antimicrobienne contre Malassezia furfur."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'ligusticum-sinense-var-sinense';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Lilium tigrinum (lis tigré) était employé traditionnellement dans diverses affections utérines et ovariennes, notamment les douleurs névralgiques, les déplacements utérins et les congestions pelviennes chroniques. On l'utilisait également contre les nausées et céphalées d'origine utérine ainsi qu'en soutien pendant la récupération post-partum."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'lilium-tigrinum';
UPDATE public.herbs SET description = $en$Linum usitatissimum L. subsp. sativa is the cultivated flax, a plant studied for its physiological and biochemical responses to abiotic stresses such as salinity and drought. Research has characterized its cyanogenic glycosides, specialized metabolites involved in herbivore defense, nitrogen mobilization, and stress responses. Gamma-aminobutyric acid (GABA) and DELLA proteins have been examined for their roles in drought tolerance and hormonal crosstalk.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Linum usitatissimum subsp. sativa est le lin cultivé, étudié autant pour ses graines riches en mucilages, lignanes et acides gras oméga-3 que pour ses métabolites spécialisés (glycosides cyanogènes, GABA, protéines DELLA) impliqués dans la réponse au stress abiotique. L'intérêt clinique repose surtout sur la graine entière et son huile."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'linum-usitatissimum-l-subsp-sativa';
UPDATE public.herbs SET description = $en$Lithospermum erythrorhizon is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for skin infections, skin inflammation, wounds, dermatitis. Documented phytochemical constituents include polysaccharides, shikonin, and naphthoquinones. Commercial adult preparations commonly formulate 1000–3000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Lithospermum erythrorhizon est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : infections cutanées, inflammation cutanée, plaies, dermatite. Les constituants phytochimiques identifiés comprennent notamment polysaccharides, shikonine et naphtoquinones. Les préparations commerciales pour adultes formulent généralement 1000–3000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'lithospermum-erythrorhizon';
UPDATE public.herbs SET description = $en$Lonicera nigra (black-berried honeysuckle, family Caprifoliaceae) is a deciduous shrub native to central and southern European mountain woodlands. Unlike Lonicera japonica, whose flower buds hold extensive pharmacopoeial documentation in East Asia, published research on L. nigra focuses primarily on ecology and microfungal host associations such as Dasyscyphus barbatus. Medicinal efficacy in humans is unestablished, and berries of European wild honeysuckles are mildly toxic.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Lonicera nigra (chèvrefeuille noir, famille des Caprifoliacées) est un arbuste montagnard d'Europe centrale et méridionale. Contrairement à Lonicera japonica utilisée en pharmacopée asiatique, L. nigra fait surtout l'objet de travaux écologiques, aucune étude clinique humaine n'étant disponible et ses baies étant considérées comme légèrement toxiques."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'lonicera-nigra';
UPDATE public.herbs SET description = $en$Ludwigia prostrata, also known as primrose-willow, is a species in the Onagraceae family. It is commonly found as a weed in paddy fields and subtropical wetlands. The plant exhibits a high capacity for accumulating heavy metals such as copper, lead, and zinc. Controlled human clinical data evaluating medicinal use are lacking, and potential heavy-metal accumulation warrants caution.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Ludwigia prostrata (famille des Onagracées) est une espèce des rizières et zones humides subtropicales étudiée pour son écologie et sa forte capacité à accumuler des métaux traces tels que le cuivre, le plomb et le zinc. Les données cliniques humaines sur un usage médicinal sont inexistantes."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'ludwigia-prostrata';
UPDATE public.herbs SET description = $en$Lycopodium japonicum is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for osteoarthritis, low back pain. Documented phytochemical constituents include fawcettimine-type alkaloids, lycojaponicumins, serratene triterpenoids, and natural tyrosinase inhibitors. Commercial adult preparations commonly formulate 1000–3000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Lycopodium japonicum est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : arthrose, lombalgies. Les constituants phytochimiques identifiés comprennent notamment alcaloïdes de type fawcettimine, lycojaponicumines, triterpénoïdes serratanes et inhibiteurs naturels de tyrosinase. Les préparations commerciales pour adultes formulent généralement 1000–3000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'lycopodium-japonicum';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "La menthe poivrée (Mentha piperita) est une herbe aromatique dont les feuilles séchées et les sommités fleuries étaient traditionnellement employées comme stimulant digestif et carminatif. Grâce à son huile essentielle riche en menthol, elle servait à calmer les nausées, soulager les crampes gastro-intestinales et expulser les gaz."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'mentha-piperita';
UPDATE public.herbs SET description = $en$Mucor racemosus e volumine cellulae is a purified extract of the fungal pathogen Mucor racemosus used in research to study innate immune responses in the human conjunctiva. It modulates intracellular calcium concentration and whole-cell currents through transient receptor potential channel subtypes in human conjunctival epithelial cells.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Mucor racemosus e volumine cellulae est un extrait fongique purifié historiquement répertorié dans des préparations biologiques ou isothérapiques. En recherche expérimentale, il a été étudié sur des cellules épithéliales conjonctivales humaines pour la signalisation calcique ; l'efficacité clinique thérapeutique chez l'humain n'est pas établie."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'mucor-racemosus-e-volumine-cellulae';
UPDATE public.herbs SET description = $en$Nardostachys grandiflora DC., commonly known as spikenard, is a commercial medicinal plant in the Valerianaceae family that is harvested for its root biomass in the hills of Nepal. It is found in alpine meadows, including regions such as the Jumla District of Nepal.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Nardostachys grandiflora DC. (nard de l'Himalaya ou jatamansi, famille des Caprifoliacées) est une plante alpine aromatique récoltée dans les régions himalayennes du Népal pour ses rhizomes riches en sesquiterpènes. Utilisée traditionnellement comme calmant nerveux, son espèce subit une pression de récolte nécessitant une gestion durable."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'nardostachys-grandiflora-dc';
UPDATE public.herbs SET description = $en$Onosmodium virginianum (Virginia false gromwell, family Boraginaceae) is a perennial herb native to dry woodlands and pine barrens of the eastern and southern United States. Its medicinal profile derives mainly from historical nineteenth-century homeopathic proving records, notably for migraine, eye strain, and neuromuscular weakness, rather than contemporary clinical pharmacology. Controlled trials in humans are absent.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Onosmodium virginianum (faux grémil de Virginie, famille des Boraginacées) est une herbacée vivace des sous-bois secs de l'est des États-Unis. Son emploi provient surtout de pathogénésies homéopathiques du XIXe siècle contre les migraines et l'asthénie neuromusculaire, sans données phytochimiques ni essais cliniques modernes."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'onosmodium-virginianum';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Oxydendrum arboreum (arbre à oseille) était utilisé traditionnellement contre l'hydropisie, particulièrement chez les personnes âgées ou affaiblies, ainsi qu'en cas d'insuffisance rénale avec mictions douloureuses. Les récits historiques mentionnent aussi son usage lors d'hypertrophie prostatique chronique et d'irritation urinaire sénile."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'oxydendrum-arboreum';
UPDATE public.herbs SET description = $en$Paeonia anomala subsp. veitchii is a plant in the subfamily Paeoniaceae, identified as an important traditional Chinese herbal medicine. Its complete chloroplast genome is 152,682 bp in length with 38.42% GC content. Closely related to Paeonia lactiflora, its dried root has long been used in East Asian herbal formulas for blood-stasis and inflammatory patterns, though standalone clinical trials remain limited.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Paeonia anomala subsp. veitchii (pivoine de Veitch, famille des Paeoniacées) est une plante importante de la médecine traditionnelle chinoise, proche de Paeonia lactiflora et employée pour la circulation sanguine et l'inflammation. Ses données cliniques spécifiques restent surtout issues de préparations traditionnelles composées."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'paeonia-anomala-subsp-veitchii';
UPDATE public.herbs SET description = $en$Paeonia obovata is a perennial herb in the Paeoniaceae family, known in folk medicine as Mountain Paeony Root. Its root contains the monoterpene glycoside 6'-O-acetylpaeoniflorin, a compound not detected in Paeonia lactiflora. The root is used in oriental and folk medicine, and it is a component of Qizhiweitong particles, a traditional Chinese medicine historically used for gastrointestinal diseases.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Paeonia obovata (racine de pivoine des montagnes, famille des Paeoniacées) renferme notamment le glycoside monoterpénique 6'-O-acétylpaéoniflorine absent chez P. lactiflora. En médecine traditionnelle d'Asie de l'Est, sa racine entre dans des formules digestives et circulatoires, sans essais cliniques isolés concluants."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'paeonia-obovata';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Pareira brava est une plante dont la racine renferme de l'amidon, des tanins et de faibles quantités d'alcaloïdes dont la pellosine. Elle était traditionnellement utilisée dans les affections chroniques des reins et de la vessie avec oligurie, sédiments uratiques, cystite, pyélite, dysurie et mictions fréquentes."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'pareira-brava';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Paullinia sorbilis (guarana ou cacao du Brésil) contient de la caféine, des tanins, une huile volatile, des saponines et de la résine. Elle était utilisée traditionnellement comme tonique, léger stimulant nerveux et antalgique, notamment contre les diarrhées persistantes et les migraines d'origine digestive."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'paullinia-sorbilis';
UPDATE public.herbs SET description = $en$Penicillium chrysogenum e volumine cellulae is a fungal material derived from the cells of the mold Penicillium chrysogenum. Secondary metabolite fractions from a P. chrysogenum strain have been studied in the laboratory for activity against HIV-1 subtypes A, B, and C and for effects on cell-to-cell viral spread. The fungus has also been used in solid-state fermentation to upgrade lignocellulosic biomass such as cotton straw.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Penicillium chrysogenum e volumine cellulae est une matière biologique dérivée de la moisissure Penicillium chrysogenum, espèce célèbre pour la production industrielle de pénicilline mais non utilisée comme plante médicinale. Des fractions métaboliques ont été étudiées uniquement en laboratoire et en fermentation de biomasse."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'penicillium-chrysogenum-e-volumine-cellulae';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Penthorum sedoides était utilisé traditionnellement dans les irritations chroniques de la gorge caractérisées par des muqueuses sèches et congestionnées. On l'employait également contre la dyspepsie atonique, la faiblesse digestive liée à l'épuisement nerveux, la diarrhée et les inflammations catarrhales des muqueuses gastro-intestinales."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'penthorum-sedoides';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Le palmier dattier (Phoenix dactylifera) produit des fruits sucrés et nutritifs. Dans les textes anciens, les dattes étaient traditionnellement employées pour apaiser l'irritation thoracique, favoriser l'expectoration, prévenir la constipation et soutenir la reprise de force et de poids chez les convalescents et les enfants."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'phoenix-dactylifera';
UPDATE public.herbs SET description = $en$Phyllostachys nigra var. henonis is a bamboo plant whose culms are the source of various glycosides and phenylpropanoids. Among the isolated compounds are five new glycosides, bambulignan B, and three new phenylpropanoids. These compounds have shown DPPH radical scavenging activity, indicating antioxidant properties.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Phyllostachys nigra var. henonis est une variété de bambou dont les chaumes ont fourni divers glycosides, phénylpropanoïdes et la lignane bambulignane B présentant une activité piégeuse de radicaux DPPH in vitro. Aucun essai clinique humain n'établit d'indication thérapeutique."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'phyllostachys-nigra-var-henonis';
UPDATE public.herbs SET description = $en$Pinus montana (syn. Pinus mugo, mountain pine, family Pinaceae) is a subalpine European conifer whose needles and young shoots yield essential oils rich in monoterpenes with documented antimicrobial and antioxidant activity in vitro. Bud preparations also supply polyphenols and resins traditionally used in aromatic steam inhalations and balms for minor upper-respiratory congestion, though controlled human trials remain limited.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Pinus montana (pin de montagne ou pin mugo) fournit des huiles essentielles et extraits de bourgeons riches en polyphénols ayant démontré in vitro des propriétés antimicrobiennes et antiradicalaires. Les usages respiratoires reposent principalement sur la tradition aromatique et balsamo-expectorante."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'pinus-montana';
UPDATE public.herbs SET description = $en$Pinus tabuliformis, known as Chinese pine, is a native conifer of northern China used for timber, fuelwood, and ecological restoration. It produces defensive chemicals including the monoterpene alpha-pinene and the phenolic compound naringenin, and its phloem contains pinitol as a main soluble carbohydrate. Pine pollen polysaccharides from Pinus sources have been noted for pharmacological activities.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Pinus tabuliformis (pin rouge de Chine) est un conifère du nord de la Chine dont les tissus produisent de l'alpha-pinène, de la naringénine et du pinitol, tandis que le pollen de pin contient des polysaccharides étudiés en préclinique. Les données cliniques humaines sur cette espèce spécifique restent rares."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'pinus-tabuliformis';
UPDATE public.herbs SET description = $en$Plantago arenaria is a pioneer plant species in the Plantaginaceae family that exhibits morphological plasticity in its shoots depending on ecological conditions such as moisture and soil density. It contains the alkaloids narcotine and arenaine, as well as mucilage.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Plantago arenaria (psyllium noir des sables, famille des Plantaginacées) contient abondamment du mucilage (arabinoxylanes) dans les téguments de ses graines ainsi que de faibles traces d'alcaloïdes comme la narcotine et l'arénaïne. Ses graines mucilagineuses partagent le profil mécanique laxatif de lest du genre Plantago."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'plantago-arenaria';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Polygonum punctatum était employé traditionnellement en cas d'aménorrhée, en particulier lorsqu'elle était déclenchée par le froid, et dans les états pléthoriques sans anémie. On lui attribuait une action sur la peau et les reins ainsi qu'un effet antispasmodique utile contre la rétention urinaire aiguë et certaines coliques flatulentes."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'polygonum-punctatum';
UPDATE public.herbs SET description = $en$Polyporus officinalis, also known as Laricifomes officinalis or Gharikon, is a wood-rotting fungus native to Europe, Asia, and North America. It grows on various hosts, including conifers. In Iranian traditional medicine, it has been used since ancient times for fever, jaundice, stomach and uterus pain, constipation, bronchitis, weakness of muscles, and sciatica.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Polyporus officinalis (syn. Laricifomes officinalis ou agaric blanc) est un polypore lignicole croissant sur les conifères d'Eurasie et d'Amérique du Nord. En médecine traditionnelle iranienne et européenne ancienne, il servait contre la fièvre, les troubles bronchiques et les sueurs nocturnes, sans validation clinique contemporaine."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'polyporus-officinalis';
UPDATE public.herbs SET description = $en$Prunus davidiana is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for liver fibrosis. Documented phytochemical constituents include flavonoids, catechin, and naringenin. Commercial adult preparations commonly formulate 1000–6000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Prunus davidiana est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : fibrose hépatique. Les constituants phytochimiques identifiés comprennent notamment flavonoïdes, catéchine et naringénine. Les préparations commerciales pour adultes formulent généralement 1000–6000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'prunus-davidiana';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Ranunculus bulbosus (renoncule bulbeuse) est une renoncule commune à saveur très âcre dont les feuilles fraîches provoquent rougeurs et phlyctènes au contact cutané. Une teinture préparée à partir de la plante était traditionnellement employée contre le zona accompagné de douleurs intercostales, ainsi que dans certaines pleurodynies et névralgies costales."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'ranunculus-bulbosus';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Le radis noir (Raphanus sativus var. niger) est une racine potagère à peau sombre et chair blanche piquante riche en huile essentielle soufrée. Traditionnellement, il était employé contre l'enrouement, la gêne respiratoire bronchique et les toux persistantes, tandis que la racine fraîche s'appliquait localement sur les cors et furoncles."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'raphanus-sativus-var-niger';
UPDATE public.herbs SET description = $en$Raphanus sativus var. sativus is the common cultivated garden radish (family Brassicaceae), grown worldwide as a crisp edible root vegetable. Cruciferous roots and leaves contain glucosinolates, isothiocyanates, vitamin C, and anthocyanins in red-skinned cultivars, contributing dietary antioxidant and culinary digestive value. Dedicated clinical trials supporting medicinal claims for concentrated therapeutic preparations remain limited.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Raphanus sativus var. sativus est le radis rouge ou rose cultivé (famille des Brassicacées), largement consommé comme légume croquant. Comme les autres crucifères, il apporte des glucosinolates, des isothiocyanates, de la vitamine C et des anthocyanes à intérêt nutritionnel et digestif, sans essais cliniques dédiés à des extraits médicinaux concentrés."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'raphanus-sativus-var-sativus';
UPDATE public.herbs SET description = $en$Rhamnus californica (syn. Frangula californica, California coffeeberry, family Rhamnaceae) is an evergreen shrub native to chaparral and riparian habitats of western North America. Indigenous groups historically prepared bark and berry decoctions for gastrointestinal, respiratory, and skin complaints. Like allied Frangula species, bark extracts likely carry hydroxyanthracene compounds with stimulant laxative potential, while modern clinical studies are lacking.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Rhamnus californica (syn. Frangula californica, nerprun de Californie) est un arbuste des chaparrals californiens traditionnellement utilisé par les peuples autochtones contre les affections gastro-intestinales, respiratoires et cutanées. Son écorce renferme probablement des anthraquinones comme les espèces voisines, mais les essais cliniques font défaut."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'rhamnus-californica';
UPDATE public.herbs SET description = $en$Rheum pumilum (dwarf Tibetan rhubarb, family Polygonaceae) is a high-altitude alpine perennial endemic to the Qinghai-Tibetan Plateau, botanically allied to Rheum palmatum, Rheum tanguticum, and Rheum officinale. It holds traditional standing in East Asian and Tibetan herbal medicine for gastrointestinal and heat-clearing formulations, though isolated clinical trials verifying standalone safety and efficacy remain limited.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Rheum pumilum (rhubarbe naine du plateau tibétain, famille des Polygonacées) est une espèce alpine endémique reconnue en médecine traditionnelle chinoise et tibétaine, apparentée à Rheum palmatum et Rheum officinale. Les données phytochimiques et cliniques isolées sur cette espèce restent encore limitées."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'rheum-pumilum';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Rhus aromatica (sumac odorant) contient une huile volatile, des résines, des tanins et de la gomme. Il était traditionnellement utilisé contre les troubles urinaires tels que la polyurie, l'énurésie nocturne de l'enfant et l'incontinence des personnes âgées, ainsi que pour modérer les saignements passifs des muqueuses et les sueurs nocturnes."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'rhus-aromatica';
UPDATE public.herbs SET description = $en$Rhus venenata (syn. Toxicodendron vernix, poison sumac, family Anacardiaceae) is a North American wetland shrub containing toxic urushiol-type skin irritants shared with Toxicodendron radicans (poison ivy). Exposure to sap, foliage, or smoke causes severe allergic contact dermatitis, blistering, and systemic toxicity upon ingestion; internal herbal use is contraindicated and not supported by clinical evidence.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Rhus venenata (syn. Toxicodendron vernix, sumac vénéneux des marais) contient des catéchols urushiols irritants identiques ou apparentés à ceux du sumac grimpant et provoque de sévères dermatites de contact allergiques. Il s'agit d'une plante toxique dont l'usage phytothérapeutique interne est contre-indiqué."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'rhus-venenata';
UPDATE public.herbs SET description = $en$Rosa laevigata is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for diabetes, nephropathy, myocardial damage, oxidative damage. Documented phytochemical constituents include flavonoids, tannins, lignans, and polysaccharides. Commercial adult preparations commonly formulate 1000–3000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Rosa laevigata est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : diabète, néphropathie, protection myocardique, stress oxydatif. Les constituants phytochimiques identifiés comprennent notamment flavonoïdes, tanins, lignanes et polysaccharides. Les préparations commerciales pour adultes formulent généralement 1000–3000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'rosa-laevigata';
UPDATE public.herbs SET description = $en$Rubus loganobaccus (loganberry, family Rosaceae) is a hybrid bramble originating from an accidental cross between a North American blackberry and a red raspberry in California. Its tart dark-red aggregate fruits are rich in vitamin C, dietary fiber, anthocyanins, and ellagitannins similar to other Rubus berries. Beyond nutritional and food uses, species-specific human clinical evidence for medicinal indications is limited.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Rubus loganobaccus (mûre de Logan, famille des Rosacées) est une ronce hybride issue d'un croisement entre mûre et framboise rouge, produisant des baies acidulées riches en vitamine C, anthocyanes et ellagitanins. Son emploi principal reste alimentaire et nutritionnel, faute d'essais cliniques dédiés à cette variété."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'rubus-loganobaccus';
UPDATE public.herbs SET description = $en$Rubus occidentalis, the black raspberry, is a black-fruited raspberry native to North America and a member of the Rosaceae family. The fruit is rich in anthocyanins such as cyanidin 3-rutinoside and cyanidin 3-xylosylrutinoside, along with ellagic acid and ellagitannins. It has been studied for anticancer, anti-inflammatory, and metabolic regulatory effects, and mechanisms include inhibition of NF-kappa B and AP-1 activation and modulation of gut microbiota.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Rubus occidentalis (framboisier noir d'Amérique du Nord, famille des Rosacées) produit des baies très riches en anthocyanes (cyanidine-3-rutinoside), en acide ellagique et en ellagitanins. Des études précliniques et pilotes explorent ses effets antioxydants, anti-inflammatoires (NF-κB, AP-1) et sur le microbiote intestinal."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'rubus-occidentalis';
UPDATE public.herbs SET description = $en$Rubus strigosus is the red raspberry species, a plant from which anthocyanin-rich extracts can be derived. Its primary active constituents are anthocyanins, which are responsible for the rich color of the extract. The species is processed into an anthocyanin-rich red raspberry extract known as ARRE.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Rubus strigosus (framboisier rouge d'Amérique du Nord) fournit des fruits riches en anthocyanes et polyphénols utilisés pour préparer des extraits antioxydants concentrés. Au-delà de la consommation alimentaire des fruits et des usages traditionnels des feuilles de framboisier, les essais cliniques propres à l'extrait de R. strigosus demeurent limités."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'rubus-strigosus';
UPDATE public.herbs SET description = $en$Saccharomyces boulardii lyo is the lyophilized probiotic yeast strain Saccharomyces cerevisiae var. boulardii, widely researched in gastroenterology rather than classical herbal medicine. Clinical trials and meta-analyses have investigated lyophilized S. boulardii as an adjunct to reduce antibiotic-associated diarrhea and prevent recurrent Clostridioides difficile diarrhea, with standard safety precautions in severely immunocompromised or central-line patients.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Saccharomyces boulardii lyo désigne la forme lyophilisée de la levure probiotique Saccharomyces cerevisiae var. boulardii. Elle est largement étudiée et employée chez l'adulte et en gastro-entérologie pour la prévention et la réduction des diarrhées associées aux antibiotiques et des récidives de diarrhée à Clostridioides difficile."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'saccharomyces-boulardii-lyo';
UPDATE public.herbs SET description = $en$Saccharum officinale L. is a sugar-producing plant in the Poaceae family, widely cultivated in tropical regions. It is a glycophytic species whose growth and productivity can be severely reduced by soil salinity. Beyond culinary sucrose, cane wax policosanols and phenolic fractions have drawn laboratory study, while controlled human clinical evidence for whole-plant extract remains limited.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Saccharum officinale (canne à sucre, famille des Poacées) est une grande graminée tropicale cultivée principalement pour le saccharose et étudiée agronomiquement pour sa tolérance à la salinité. Au-delà des dérivés alimentaires et cires végétales (policosanols), les essais cliniques thérapeutiques sont limités."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'saccharum-officinale';
UPDATE public.herbs SET description = $en$Salix vitellina (golden willow, classified botanically within Salix alba subsp. vitellina, family Salicaceae) is a cultivated ornamental willow distinguished by bright yellow-orange winter shoots. Like white willow (Salix alba), bark of closely allied willows contains phenolic glycosides related to salicin, historically studied for mild analgesic and antipyretic actions. Human clinical trials isolating S. vitellina itself are lacking.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Salix vitellina (osier jaune, rattaché à Salix alba, famille des Salicacées) est une variété de saule aux jeunes rameaux jaune vif. À l'instar du saule blanc (Salix alba), l'écorce des saules apparentés contient des dérivés salicylés tels que la salicine, bien qu'aucun essai clinique ne porte spécifiquement sur S. vitellina."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'salix-vitellina';
UPDATE public.herbs SET description = $en$Salvia chinensis is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for hepatocellular carcinoma, colorectal cancer adjuvant therapy. Documented phytochemical constituents include quercetin, sesquiterpenes, ursolic acid, and rosmarinic acid. Commercial adult preparations commonly formulate 1000–1500 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Salvia chinensis est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : contexte hépatocellulaire, soutien complémentaire en contexte de cancer colorectal. Les constituants phytochimiques identifiés comprennent notamment quercétine, sesquiterpènes, acide ursolique et acide rosmarinique. Les préparations commerciales pour adultes formulent généralement 1000–1500 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'salvia-chinensis';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Le sureau du Canada (Sambucus nigra subsp. canadensis) est un arbuste à rameaux creux portant des ombelles de fleurs parfumées et des baies sombres légèrement acidulées. L'écorce interne des jeunes rameaux servait autrefois de purgatif, les fleurs entraient dans des pommades oculaires et le jus des baies était utilisé contre les refroidissements et comme laxatif doux."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'sambucus-nigra-subsp-canadensis';
UPDATE public.herbs SET description = $en$Saxifraga granulata (meadow saxifrage, family Saxifragaceae) is a gynodioecious perennial native to damp meadows and riparian grasslands of central Europe, including Belgium, Luxembourg, and Germany. While small basal bulbils led to occasional mention in older European herbals, contemporary biomedical literature focuses on habitat conservation rather than pharmacology, and human clinical evidence is absent.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Saxifraga granulata (saxifrage granulée, famille des Saxifragacées) est une vivace des prairies humides d'Europe centrale en déclin écologique. Historiquement mentionnée dans d'anciens herbiers européens pour ses petits bulbilles basaux, elle ne dispose pas d'essais cliniques ni de profil pharmacologique moderne établi."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'saxifraga-granulata';
UPDATE public.herbs SET description = $en$Scaphium lychnophorum (syn. Sterculia lychnophora, malva nut or Pang Da Hai, family Malvaceae) is a Southeast Asian tropical tree cultivated in southern China and Malaysia for its mucilage-rich seeds. When soaked in water, the seed coat swells into a soothing demulcent gel traditionally prepared in East Asia for sore throat, hoarseness, and cough; controlled human clinical trials remain limited.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Scaphium lychnophorum (syn. Sterculia lychnophora, graine de Pang Da Hai ou noix de Malva) est un arbre tropical asiatique cultivé notamment dans le Yunnan dont les graines mucilagineuses gonflent dans l'eau et sont utilisées en médecine traditionnelle chinoise pour apaiser la gorge et les cordes vocales."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'scaphium-lychnophorum';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "La scille maritime (Scilla maritima) était employée traditionnellement à faible dose pour apaiser l'irritation bronchique et faciliter l'expectoration dans l'asthme et la toux chronique post-pneumonique. Elle servait également comme diurétique dans l'hydropisie et, en usage externe, contre certaines piqûres et ulcères torpides."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'scilla-maritima';
UPDATE public.herbs SET description = $en$Scurrula parasitica is a hemiparasitic shrub in the Loranthaceae family, widespread in southern China and Southeast Asia. It contains a range of compounds including triterpenoid esters, uvaol, ursolic acid derivatives, cardiac glycosides, flavonoids, and polysaccharides. Polysaccharides from the plant have been studied for their effects on sarcoma S180 in animal models, where they down-regulated Ki-67, CyclinD1, and Bcl-2 and up-regulated Bax.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Scurrula parasitica (gui parasite d'Asie du Sud-Est, famille des Loranthacées) renferme des esters triterpénoïdes, de l'uvaol, des dérivés d'acide ursolique, des flavonoïdes et des polysaccharides. Des fractions polysaccharidiques ont montré des effets antiprolifératifs sur le sarcome S180 murin en laboratoire, sans essais cliniques humains."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'scurrula-parasitica';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Senecio aureus (séneçon doré) était décrit traditionnellement comme un tonique des tissus nerveux et musculaires de l'appareil reproducteur féminin. On l'employait contre l'irrégularité menstruelle, les leucorrhées, la congestion pelvienne, certains troubles génito-urinaires et la constipation d'origine utérine."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'senecio-aureus';
UPDATE public.herbs SET description = $en$Si Wu Tang, also known as Four Substance Decoction or Four Things Soup, is a classic formula in traditional Chinese medicine often described as the most important blood-nourishing formula for women. It is traditionally used for blood deficiency and is recorded for menstrual irregularity, anemia, and dull complexion. The formula's active compounds on record include ligustilide, ferulic acid, paeoniflorin, and catalpol. As a multi-herb formula, clinical evidence varies across preparations and targeted indications.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Si Wu Tang (Décoction des quatre substances : Rehmannia glutinosa, Angelica sinensis, Paeonia lactiflora et Ligusticum chuanxiong) est une formule classique de médecine traditionnelle chinoise employée pour nourrir et harmoniser le sang lors d'irrégularités menstruelles ou d'anémie fonctionnelle. Les principes recensés incluent ligustilide, acide férulique, paéoniflorine et catalpol."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'si-wu-tang-patent';
UPDATE public.herbs SET description = $en$Sigesbeckia glabrescens is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for rheumatic arthralgia, aching and weakness of the loins and knees, numbness of the limbs, rheumatism. Documented phytochemical constituents include sesquiterpene lactones, and diterpenes. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Sigesbeckia glabrescens est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : arthralgies rhumatismales, faiblesse et douleurs lombaires et articulaires des genoux, engourdissement des membres, rhumatismes. Les constituants phytochimiques identifiés comprennent notamment lactones sesquiterpéniques et diterpènes. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'sigesbeckia-glabrescens';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "La moutarde blanche (Sinapis alba) est une plante de la famille des Brassicacées. Les sources historiques, notamment l'American Materia Medica d'Ellingwood (1919), décrivent la moutarde comme émétique, stimulante et révulsive active, avec des propriétés anodines marquées. Appliquée sur la peau, elle produit une sensation de brûlure intense et une inflammation violente; une application prolongée peut entraîner une ulcération. Prise par voie interne en grande quantité, si elle ne provoque pas de vomissement, elle cause une sensation de brûlure et une forme légère de gastrite. En usage externe, elle est indiquée pour les douleurs aiguës et lancinantes, localisées, souvent intermittentes, résultant d'une inflammation aiguë se développant rapidement. En usage interne, elle est indiquée pour provoquer le vomissement en cas d'ingestion de poisons non corrosifs, de corps étranger dans l'œsophage ou de détresse due à un estomac surchargé."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'sinapis-alba-herb';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "La moutarde noire (Sinapis nigra) s'utilisait traditionnellement par voie externe en cataplasme révulsif pour soulager rapidement les douleurs aiguës localisées d'inflammation récente, notamment thoraciques, et en bains stimulants. Par voie interne, elle servait autrefois de vomitif d'urgence en cas d'intoxication non corrosive."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'sinapis-nigra';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Smilax officinalis, aussi appelée salsepareille, est une plante grimpante de la famille des Smilacacées. La racine (rhizome) de Smilax officinalis, Kunth, est la source officielle de la salsepareille de la Jamaïque, ainsi nommée parce qu'elle était autrefois obtenue d'Amérique centrale et expédiée via cette île. La plante est une liane à tige anguleuse, épineuse et ligneuse, dont les jeunes pousses sont inermes. Les feuilles sont ovales-oblongues, aiguës, cordées, réticulées, à 5 ou 7 nervures, coriaces, lisses et mesurent environ 1 pied de long. Smilax officinalis pousse dans les forêts marécageuses du Mexique et des territoires s'étendant jusqu'au nord du Brésil. La salsepareille de commerce provient de plusieurs espèces de Smilax, dont Smilax officinalis, Smilax medica et Smilax papyracea, et parfois d'espèces non déterminées. La racine est utilisée en médecine traditionnelle et figure dans les pharmacopées anciennes. La racine de Smilax aspera est utilisée dans le sud de l'Europe comme substitut de la salsepareille, mais elle a peu de réputation. La salsepareille des Indes orientales, autrefois attribuée à cette espèce de Smilax, est le produit de Hemidesmus indicus. Toutes les espèces de Smilax sont des plantes grimpantes ou rampantes à tiges épineuses, caractère exprimé par le nom du médicament, dérivé de deux mots espagnols (zarza parilla) signifiant petite vigne épineuse."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'smilax-officinalis';
UPDATE public.herbs SET description = $en$Sparganium eurycarpum (broadfruit bur-reed, family Typhaceae) is an emergent perennial wetland macrophyte native to North American marshes, closely allied to the Asian medicinal species Sparganium stoloniferum (San Leng). In East Asian materia medica, rhizomes of the Sparganium genus are used in multi-herb formulas for blood stasis and menstrual discomfort. Dedicated phytochemical or human clinical trials specific to North American S. eurycarpum are lacking.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Sparganium eurycarpum (rubanier à gros fruits, famille des Typhacées) est une plante aquatique vivace des marais nord-américains, proche parente de Sparganium stoloniferum (San Leng) utilisé en médecine traditionnelle chinoise pour activer la circulation sanguine. Aucune étude clinique humaine ni caractérisation phytochimique poussée n'est disponible pour S. eurycarpum."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'sparganium-eurycarpum';
UPDATE public.herbs SET description = $en$Spartium scoparium L., also known as Sarothamnus scoparius W. and commonly called Broom, is a plant that contains the compound sparteine. Sparteine has been identified in specimens from Umbria. The plant has been studied for its relationship to the cardiovascular system.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Spartium scoparium (syn. Cytisus scoparius, genêt à balais, famille des Fabacées) est un arbuste contenant l'alcaloïde quinolizidinique spartéine aux effets cardiovasculaires et utérotoniques puissants. En raison de la toxicité de ses alcaloïdes, son emploi thérapeutique non encadré est déconseillé."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'spartium-scoparium';
UPDATE public.herbs SET description = $en$Spiraea ulmaria, commonly known as meadowsweet, is a plant that contains the compound salicin. It has been investigated in veterinary applications for skin conditions and parasite control. In a veterinary case report, a supplement containing Spiraea ulmaria and willow was considered a possible cause of life-threatening gastrointestinal bleeding in a dog.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Spiraea ulmaria (syn. Filipendula ulmaria, reine-des-prés) est une plante vivace renfermant de la salicine et d'autres dérivés salicylés, traditionnellement utilisée pour les douleurs articulaires et états fébriles mineurs. En médecine vétérinaire, une association concentrée avec du saule a déjà été suspectée d'hémorragie digestive chez le chien, rappelant la prudence salicylée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'spiraea-ulmaria';
UPDATE public.herbs SET description = $en$Spiranthes autumnalis (syn. Spiranthes spiralis, autumn lady's-tresses, family Orchidaceae) is a small slender terrestrial orchid native to European calcareous grasslands and Mediterranean meadows. Academic literature on S. autumnalis examines its spiraled inflorescence morphology and pollination biology rather than phytochemistry or medicine. Controlled clinical data establishing medicinal efficacy or safe dosing in humans do not exist.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Spiranthes autumnalis (spiranthe d'automne, syn. Spiranthes spiralis, famille des Orchidacées) est une petite orchidée terrestre des pelouses calcaires européennes et méditerranéennes. La littérature scientifique s'intéresse presque exclusivement à sa morphologie florale et à sa pollinisation, sans données cliniques ou pharmacologiques établies chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'spiranthes-autumnalis';
UPDATE public.herbs SET description = $en$Sprekelia formosissima, also known as Zephyranthes formosissima and commonly called Aztec Lily, Jacobean Lily, or St James Lily, is a spectacular Mexican bulb with brilliant red asymmetric flowers. It has been used traditionally in Aztec medicine for fever and infections, and in Mexican folk medicine for pain and inflammation. The bulbs contain alkaloids including lycorine, haemanthamine, tazettine, and haemanthidine, as well as flavonoids.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Sprekelia formosissima (lys aztèque ou lys de Saint-Jacques, famille des Amaryllidacées) est une plante bulbeuse du Mexique utilisée autrefois en médecine traditionnelle mexicaine contre la fièvre, l'inflammation et la douleur. Ses bulbes contiennent des alcaloïdes d'amaryllidacées potentiellement toxiques (lycorine, hémantamine) et des flavonoïdes ; aucune donnée clinique n'existe."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'sprekelia-formosissima';
UPDATE public.herbs SET description = $en$Stemona japonica is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for cough, tuberculosis. Documented phytochemical constituents include alkaloids, tuberostemonine, maistemonine, and isomaistemonine. Commercial adult preparations commonly formulate 1000–4000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Stemona japonica est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : toux, toux chronique et tuberculose historique. Les constituants phytochimiques identifiés comprennent notamment alcaloïdes, tubérostémonine, maistémonine et isomaistémonine. Les préparations commerciales pour adultes formulent généralement 1000–4000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'stemona-japonica';
UPDATE public.herbs SET description = $en$Sticta pulmonacea is a lichenized fungus in the order Peltigerales that forms symbiotic associations with green algae or cyanobacteria, sometimes both. Metabolomic studies of the genus have identified lipids, small phenolic compounds, saturated acids, terpenes, and phenolic lichen compounds such as depsides, depsidones, and anthraquinones. Specific constituents include sticticin, stictamides A to C, and carbohydrates such as gentiobiose and various polysaccharides. Stictamide A inhibits MMP12 at 2.3 micromolar and reduced invasion in a human glioma cell line.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Sticta pulmonacea est un lichen symbiotique des forêts tempérées appartenant aux Peltigérales. Les analyses métabolomiques ont identifié des depsides, depsidones, anthraquinones, sticticine et stictamides A à C ; la stictamide A inhibe la métalloprotéinase MMP12 à 2,3 µM in vitro, sans essai clinique chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'sticta-pulmonacea';
UPDATE public.herbs SET description = $en$Sticta pulmonaria (lungwort lichen, syn. Lobaria pulmonaria) is a large foliose lichen growing symbiotically on temperate woodland bark, historically documented in eclectic and homeopathic materia medica. In historical practice it was prepared as dilutions or tinctures for dry irritative coughs, nasal congestion, laryngitis, and neck or shoulder soreness. Verified active constituents and modern controlled human clinical trials are lacking.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Sticta pulmonaria (pulmonaire des chênes, syn. Lobaria pulmonaria) est un grand lichen foliacé poussant sur les écorces forestières, mentionné historiquement dans les matières médicales éclectiques et homéopathiques contre la toux sèche irritative, la congestion nasale, la laryngite et les douleurs scapulaires. Les essais cliniques contrôlés modernes font défaut."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'sticta-pulmonaria';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Syzygium jambolanum (jambul ou jamelonier) est un arbre dont l'écorce et surtout les graines étaient utilisés traditionnellement dans le diabète afin de réduire la glycosurie et soutenir la vitalité. L'écorce et les feuilles astringentes servaient aussi contre la diarrhée, les douleurs rhumatismales et les ulcères torpides."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'syzygium-jambolanum';
UPDATE public.herbs SET description = $en$Taraxacum sinicum is a plant species whose roots and leaves contain phenolic acids and flavonoids, including caffeic acid, chlorogenic acid, ferulic acid, luteolin, diosmetin, caftaric acid, cichoric acid, quercetin, apigenin, and taraxasterol. A specific strain, Binpu-3, may be cultivated in slightly saline-alkali soil. Its root extract has been studied for inhibiting tumor invasion via the Notch signaling pathway in Drosophila and human breast cancer cells.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Taraxacum sinicum (pissenlit chinois) renferme dans ses racines et feuilles des acides phénoliques (caféique, chlorogénique, férulique, cichorique) et flavonoïdes (lutéoline, apigénine, quercétine, taraxastérol). Des extraits de racine ont été étudiés in vitro pour l'inhibition de l'invasion cellulaire tumorale via la voie Notch, sans validation clinique humaine."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'taraxacum-sinicum';
UPDATE public.herbs SET description = $en$Teucrium scorodonia L. is a plant species with recognized subspecies, including T. scorodonia subsp. scorodonia from Corsica and T. scorodonia subsp. baeticum from western Algeria. Its essential oils contain germacrene B and gamma-elemene, and it hosts endophytic fungi such as Geniculosporium sp.1, which produces geniculol and cytochalasin F. Cytochalasin F acts as an inhibitor of photosynthesis.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Teucrium scorodonia (germandrée des bois, famille des Lamiacées) comprend plusieurs sous-espèces méditerranéennes et européennes dont l'huile essentielle renferme du germacrène B et du gamma-élémène, et qui héberge des endophytes produisant de la cytochalasine F. Les essais cliniques humains manquent et plusieurs espèces de Teucrium exigent prudence hépatique."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'teucrium-scorodonia';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Thea sinensis est le théier, dont les feuilles renferment de la caféine et des polyphénols. Historiquement, la caféine contenue dans le thé a été décrite pour stimuler la vigilance cérébrale, augmenter légèrement le débit urinaire par action rénale et soutenir la contraction cardiaque tout en dilatant certains vaisseaux périphériques."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'thea-sinensis';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Trillium pendulum (trille dressé) était réputé exercer un effet modérateur sur l'innervation thoracique et les muqueuses sécrétantes. Il était traditionnellement employé contre la bronchite catarrhale avec expectoration abondante, l'hémoptysie débutante, ainsi que dans les saignements utérins passifs (ménorragies, métrorragies) et les pertes vaginales."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'trillium-pendulum';
UPDATE public.herbs SET description = $en$Triticum aestivum subsp. spelta (spelt wheat, family Poaceae) is an ancient hulled hexaploid wheat cultivated primarily as a grain crop for bread and baked foods. Analyzed spelt genotypes typically show grain protein levels spanning 12.1% to 22.2%, along with dietary fiber, minerals, and gluten proteins requiring avoidance in celiac disease. Apart from whole-grain nutritional value, specific medicinal extracts lack clinical trial support.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Triticum aestivum subsp. spelta (grand épeautre, famille des Poacées) est une céréale hexaploïde ancienne cultivée principalement pour la panification et la nutrition. Ses grains présentent une teneur en protéines de 12,1 % à 22,2 % et contiennent du gluten ; son intérêt est alimentaire plutôt que soutenu par des essais cliniques pharmacologiques."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'triticum-aestivum-subsp-spelta';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Turnera aphrodisiaca (damiana) était décrite comme un tonique nerveux doux originaire du Mexique où elle est utilisée traditionnellement comme stimulant sexuel. Les médecins d'autrefois la recommandaient dans l'impuissance, la neurasthénie sexuelle, la perte de libido, le catarrhe urinaire ou respiratoire et les irrégularités menstruelles."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'turnera-aphrodisiaca';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "La damiana (Turnera diffusa var. aphrodisiaca) est un petit arbuste d'Amérique tropicale aux petites fleurs jaunes et capsules globuleuses dont on utilise les feuilles et extrémités fleuries. Elle a été employée traditionnellement comme stimulant général et pour les troubles nerveux et reproductifs."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'turnera-diffusa-var-aphrodisiaca';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "L'orme rouge (Ulmus fulva) fournit une écorce interne riche en mucilage adoucissant traditionnellement utilisée pour tapisser et calmer les muqueuses irritées lors de diarrhée, dysenterie ou inflammation urinaire. Appliquée à l'extérieur en cataplasme émollient, l'écorce servait aussi à apaiser les inflammations cutanées locales."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'ulmus-fulva';
UPDATE public.herbs SET description = $en$Ulmus procera, known as the English elm, is a tree species identified as a 2,000-year-old Roman clone. It derives from a single clone transported by Romans from Italy to the Iberian peninsula and then to Britain to support and train vines. The tree is characterized by efficient vegetative reproduction and an inability to set seeds.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Ulmus procera (orme champêtre anglais) est un grand arbre caduc diffusé en Europe depuis l'Antiquité par multiplication végétative. Comme d'autres ormes européens, son écorce astringente a figuré dans d'anciens herbiers populaires, mais la littérature moderne porte surtout sur sa biologie clonale plutôt que sur des essais cliniques."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'ulmus-procera';
UPDATE public.herbs SET description = $en$Uncaria hirsuta is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for hypertension, fevers, headaches, gastrointestinal illness. Documented phytochemical constituents include indole alkaloids, and chlorogenic acid. Commercial adult preparations commonly formulate 1000–3000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Uncaria hirsuta est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : hypertension, états fébriles, céphalées, affections digestives. Les constituants phytochimiques identifiés comprennent notamment alcaloïdes indoliques et acide chlorogénique. Les préparations commerciales pour adultes formulent généralement 1000–3000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'uncaria-hirsuta';
UPDATE public.herbs SET description = $en$Vaccaria hispanica subsp. hispanica is a herb whose seeds contain the flavonoid glycoside vaccarin. It is also known as a Chinese herb used in botanical combinations. Research has examined vaccarin for renal ischemia-reperfusion injury and extracts for cancer cell growth inhibition.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Vaccaria hispanica subsp. hispanica (saponaire des vaches / Wang Bu Liu Xing, famille des Caryophyllacées) est une herbe dont les graines contiennent le glycoside flavonoïde vaccarine, utilisée en médecine traditionnelle chinoise dans des formules circulatoires. Les études sur la vaccarine demeurent précliniques."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'vaccaria-hispanica-subsp-hispanica';
UPDATE public.herbs SET description = $en$Vaccinium myrsinites (shiny blueberry, family Ericaceae) is a low-growing evergreen shrub native to sandy pine flatwoods and scrub habitats in the southeastern United States. Existing peer-reviewed studies examine plant-herbivore ecology and evolutionary relationships within Vaccinium section Cyanococcus rather than human phytotherapy. Specific bioactive constituent yields and human clinical trials have not been established.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Vaccinium myrsinites (airelle luisante, famille des Éricacées) est un petit arbuste sempervirent des pinèdes sableuses du sud-est des États-Unis. Les études scientifiques portent surtout sur l'écologie végétale et l'herbivorie au sein du genre Vaccinium ; aucun essai clinique ni profil pharmacologique humain n'est établi."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'vaccinium-myrsinites';
UPDATE public.herbs SET description = $en$Vaccinium pallidum (Blue Ridge or hillside blueberry, family Ericaceae) is a deciduous lowbush blueberry species endemic to eastern and central North America within Vaccinium section Cyanococcus. While related wild Vaccinium berries are rich in anthocyanins and polyphenols, peer-reviewed research isolating V. pallidum for clinical human indications is scarce. Dietary berry consumption provides general polyphenol intake, whereas therapeutic efficacy remains unstudied.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Vaccinium pallidum (bleuet des collines, famille des Éricacées) est une espèce sauvage nord-américaine de myrtille arbustive caduque. Bien que les baies du genre Vaccinium soient riches en anthocyanes et polyphénols, aucune étude clinique humaine spécifique ne valide d'usage thérapeutique ciblé pour cette espèce."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'vaccinium-pallidum';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Veratrum viride (vératre vert d'Amérique) renferme des alcaloïdes puissants tels que la jervine, la rubijervine et la protovératrine. Sur le plan historique, il a été utilisé par les médecins éclectiques et classiques dans les états fébriles aigus et pour abaisser la pression artérielle élevée, usage aujourd'hui abandonné en raison de sa toxicité étroite."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'veratrum-viride';
UPDATE public.herbs SET description = $en$Vincetoxicum glaucescens is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for acute bronchitis, chronic bronchitis, chronic cough. Detailed phytochemical and clinical pharmacokinetic profiling of the whole botanical remains limited. Commercial adult preparations commonly formulate 1000–3000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Vincetoxicum glaucescens est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : bronchite aiguë, bronchite chronique, toux chronique. La caractérisation phytochimique et clinique complète de la plante demeure limitée. Les préparations commerciales pour adultes formulent généralement 1000–3000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'vincetoxicum-glaucescens';
UPDATE public.herbs SET description = $en$Vincetoxicum pycnostelma is a medicinal plant whose roots and rhizomes are of pharmaceutical importance. It is utilized in traditional Chinese medicine and contains abundant anti-tumor and anti-inflammatory active compounds. The plant has been historically used in traditional practice, and its roots and rhizomes are the primary parts of interest.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Vincetoxicum pycnostelma (syn. Cynanchum paniculatum, Xu Chang Qing) est une plante médicinale dont les racines et rhizomes sont utilisés en médecine traditionnelle chinoise pour leurs effets anti-inflammatoires et antalgiques dans les affections rhumatismales ou cutanées. Les essais cliniques contrôlés modernes sont limités."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'vincetoxicum-pycnostelma';
UPDATE public.herbs SET description = $en$Viola philippica var. philippica is an edible wild plant valued for its flavor and health-promoting properties. Its leaf extracts contain phenolic compounds, flavonoids, essential minerals such as potassium, calcium, and magnesium, and fatty acids including palmitic, linoleic, oleic, and alpha-linolenic acids. In vitro studies show that leaf extracts inhibit alpha-glucosidase and pancreatic lipase, suggesting potential metabolic effects.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Viola philippica var. philippica (violette sauvage de Manchourie / Zi Hua Di Ding) est une plante comestible et médicinale riche en flavonoïdes, composés phénoliques, minéraux et acides gras insaturés. Des extraits foliaires inhibent l'alpha-glucosidase et la lipase pancréatique in vitro, sans essai clinique humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'viola-philippica-var-philippica';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "La vigne cultivée (Vitis vinifera) a connu divers emplois médicinaux historiques selon la maturité de ses fruits : les baies vertes acides servaient à évacuer la bile, tandis que les raisins mûrs et sucrés étaient donnés pour nourrir et fortifier les personnes affaiblies ou convalescentes."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'vitis-vinifera';
UPDATE public.herbs SET description = $en$Vitis vinifera var. tinctoria is a vine cultivar group that includes Alicante, Carignan, and Grand noir. Its leaves contain specific flavonoids, including hyperin, isoquercitrin, and quercetin 3-O-beta-D glucuronic acid. In European phytotherapy, red vine leaf extracts standardized in polyphenolic flavonoids are prepared for chronic venous insufficiency, swollen heavy legs, and superficial capillary fragility.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Vitis vinifera var. tinctoria regroupe les cépages teinturiers de vigne rouge (Alicante, Carignan, Grand Noir) dont les feuilles sont riches en flavonoïdes spécifiques (hypérine, isoquercitrine, quercétine-3-O-glucuronide). Les extraits de feuille de vigne rouge sont reconnus en Europe contre l'insuffisance veineuse chronique et la fragilité capillaire."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'vitis-vinifera-var-tinctoria';
UPDATE public.herbs SET description = $en$Wurfbainia longiligularis is a botanical species used in Traditional Chinese Medicine and related East Asian herbal traditions. In traditional materia medica, it has been applied for gastrointestinal diseases. Documented phytochemical constituents include terpenoids, monoterpenes, and sesquiterpenes. Commercial adult preparations commonly formulate 1000–3000 mg daily. Clinical trial evidence in humans remains limited, so listed applications reflect documented traditional usage rather than established clinical efficacy.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Wurfbainia longiligularis est une espèce botanique employée en médecine traditionnelle chinoise et dans les traditions phytothérapeutiques d'Asie de l'Est. Dans la matière médicale traditionnelle, elle est mentionnée pour : troubles gastro-intestinaux. Les constituants phytochimiques identifiés comprennent notamment terpénoïdes, monoterpènes et sesquiterpènes. Les préparations commerciales pour adultes formulent généralement 1000–3000 mg par jour. Les essais cliniques contrôlés chez l'humain demeurant limités, les usages mentionnés reflètent la tradition documentée plutôt qu'une efficacité clinique démontrée."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'wurfbainia-longiligularis';
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Wurfbainia vera est une plante médicinale dont les extraits et les huiles essentielles sont étudiés pour leurs propriétés antioxydantes, antimicrobiennes et de modulation de la morphologie intestinale. Son huile essentielle est composée à 84,00 % d'eucalyptol. Dans des modèles aviaires, les extraits modulent la fonction antioxydante et la morphologie intestinale par des interactions entre le microbiote intestinal et les métabolites. Elle est également mentionnée en médecine traditionnelle chinoise, bien que les données cliniques chez l'humain restent limitées."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'wurfbainia-vera';
UPDATE public.herbs SET description = $en$Xerophyllum asphodeloides, commonly known as eastern turkeybeard, is an herbaceous perennial native to eastern North America. It belongs to the family Xerophyllaceae and is currently ranked as Imperiled to Critically Imperiled in several states due to habitat destruction and decline.$en$, translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || $fp${"description": "Xerophyllum asphodeloides (barbe de dindon de l'Est, famille des Mélanthiacées) est une herbacée vivace d'Amérique du Nord actuellement menacée dans plusieurs États américains. Ses données botaniques portent principalement sur sa conservation écologique, sans caractérisation phytochimique ni essai clinique chez l'humain."}$fp$::jsonb, true), updated_at = now() WHERE slug = 'xerophyllum-asphodeloides';

COMMIT;
